window.COURSE={"units": [{"id": "cells", "title": "Cell biology", "subtitle": "Cells, division and transport", "paper": [1]}, {"id": "organisation", "title": "Organisation", "subtitle": "Digestion, circulation and plants", "paper": [1]}, {"id": "infection", "title": "Infection and response", "subtitle": "Pathogens, immunity and medicines", "paper": [1]}, {"id": "bioenergetics", "title": "Bioenergetics", "subtitle": "Photosynthesis and respiration", "paper": [1]}, {"id": "homeostasis", "title": "Homeostasis and response", "subtitle": "Coordination and control", "paper": [2]}, {"id": "inheritance", "title": "Inheritance, variation and evolution", "subtitle": "Genes and changing populations", "paper": [2]}, {"id": "ecology", "title": "Ecology", "subtitle": "Ecosystems and sustainability", "paper": [2]}], "lessons": [{"id": "b-cells", "unit": "cells", "title": "Animal, plant and bacterial cells", "spec": "4.1.1.1–4.1.1.2", "paper": [1], "tier": "all", "separate": false, "summary": "Nuclei contain genetic material; ribosomes make proteins; mitochondria carry out aerobic respiration.", "notes": [{"title": "Understand the biology", "html": "<p>Nuclei contain genetic material; ribosomes make proteins; mitochondria carry out aerobic respiration. Cytoplasm supports many reactions and membranes control movement. Photosynthetic plant cells also have chloroplasts, cellulose walls and a permanent vacuole.<\/p>"}, {"title": "Apply and explain", "html": "<p>Bacteria have a membrane, wall, cytoplasm and ribosomes but no nucleus. Their main DNA forms a loop; plasmids are extra DNA rings. Underground root hair cells normally lack chloroplasts, so do not draw every plant cell as a photosynthetic leaf cell.<\/p>"}], "keypoints": ["Nuclei contain genetic material; ribosomes make proteins; mitochondria carry out aerobic respiration.", "Bacteria have a membrane, wall, cytoplasm and ribosomes but no nucleus."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which structure makes proteins?", "opts": ["Ribosome", "Mitochondrion", "Cell wall"], "a": 0, "why": "Ribosome"}, {"q": "Where is the main bacterial DNA?", "opts": ["Free in cytoplasm", "Inside a nucleus", "Inside a chloroplast"], "a": 0, "why": "Free in cytoplasm"}], "exam": [{"q": "Explain three differences between a typical photosynthetic plant cell and a bacterial cell.", "m": 3, "ms": ["Plant DNA is enclosed in a nucleus; bacterial DNA is not.", "The plant cell has chloroplasts; the bacterium does not.", "The plant cell has a permanent vacuole; the bacterium does not."]}]}, {"id": "b-microscopy", "unit": "cells", "title": "Microscopy and magnification", "spec": "4.1.1.5", "paper": [1], "tier": "all", "separate": false, "summary": "Magnification enlarges an image; resolution distinguishes close points.", "notes": [{"title": "Understand the biology", "html": "<p>Magnification enlarges an image; resolution distinguishes close points. Electron microscopes reveal finer detail than light microscopes because they have greater resolution as well as greater magnification. Enlarging a blurry image does not reveal new detail.<\/p>"}, {"title": "Apply and explain", "html": "<p>Magnification = image size ÷ actual size. Convert units before dividing: 1 mm = 1000 μm. A 36 mm image representing a 12 μm cell has magnification 36000 ÷ 12 = 3000. Magnification has no unit.<\/p>"}], "keypoints": ["Magnification enlarges an image; resolution distinguishes close points.", "Magnification = image size ÷ actual size."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "A 20 μm cell appears 40 mm long. Calculate magnification.", "a": 2000, "unit": "", "tol": 0.005, "why": "40000 μm ÷ 20 μm = 2000."}, {"q": "What distinguishes two close organelles?", "opts": ["Darker labels", "High resolution", "A larger print alone"], "a": 1, "why": "High resolution"}], "exam": [{"q": "A cell image is 54 mm wide at ×1800. Calculate actual width in micrometres.", "m": 3, "ms": ["Actual size = image size / magnification.", "54/1800 = 0.03 mm.", "0.03 mm = 30 μm."]}], "sim": "magnification", "practical": {"title": "Required practical 1 · Light microscopy", "method": ["Place a thin plant tissue layer on a slide, add suitable stain and lower a coverslip at an angle.", "Start on low power and focus with coarse then fine adjustment; increase power as appropriate.", "Observe plant and prepared animal cells; make clear proportional labelled drawings with a scale or magnification."], "variables": ["Keep specimen thickness and illumination suitable.", "Record eyepiece and objective magnifications."], "safety": ["Handle glass slides carefully.", "Avoid stain contact and follow school eye-protection guidance."], "analysis": "Use image size divided by magnification for actual size, with consistent units. Total microscope magnification equals eyepiece × objective."}}, {"id": "b-specialisation", "unit": "cells", "title": "Specialisation and differentiation", "spec": "4.1.1.3–4.1.1.4", "paper": [1], "tier": "all", "separate": false, "summary": "Differentiation develops specialised structures.", "notes": [{"title": "Understand the biology", "html": "<p>Differentiation develops specialised structures. Most animal cells differentiate early; many plant cells retain this ability throughout life. Mature animal cell division mainly supports repair and replacement. Explain why a feature suits a task rather than merely listing features.<\/p>"}, {"title": "Apply and explain", "html": "<p>Sperm have a tail for swimming and many mitochondria. Nerve cells have long extensions for impulse transmission; muscle cells have contractile proteins. Root hairs enlarge absorbing area. Hollow lignified xylem conducts water; living phloem transports sugars.<\/p>"}], "keypoints": ["Differentiation develops specialised structures.", "Sperm have a tail for swimming and many mitochondria."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "What is differentiation?", "opts": ["All cells losing DNA", "Fusion of gametes", "Developing specialised cell structures"], "a": 2, "why": "Developing specialised cell structures"}, {"q": "Why is a root hair useful?", "opts": ["It makes the root photosynthesise", "It prevents mineral uptake", "It increases absorbing area"], "a": 2, "why": "It increases absorbing area"}], "exam": [{"q": "Explain three adaptations of a sperm cell for fertilisation.", "m": 3, "ms": ["A tail allows movement towards an egg.", "Many mitochondria support respiration for movement.", "Enzymes in the head help penetrate egg coverings."]}]}, {"id": "b-mitosis", "unit": "cells", "title": "Mitosis and the cell cycle", "spec": "4.1.2.1–4.1.2.2", "paper": [1], "tier": "all", "separate": false, "summary": "Chromosomes contain DNA and many genes; body cells normally have chromosome pairs.", "notes": [{"title": "Understand the biology", "html": "<p>Chromosomes contain DNA and many genes; body cells normally have chromosome pairs. Before division, a cell grows, increases its organelles and copies its DNA. These preparations give daughter cells complete genetic information and cell machinery.<\/p>"}, {"title": "Apply and explain", "html": "<p>During mitosis, chromosome copies separate and nuclei divide. Cytoplasm and membrane then divide to form two genetically identical cells with the original chromosome number. Mitosis supports growth and repair, whereas meiosis forms gametes.<\/p>"}], "keypoints": ["Chromosomes contain DNA and many genes; body cells normally have chromosome pairs.", "During mitosis, chromosome copies separate and nuclei divide."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Three cells each complete two rounds of division. How many result?", "a": 12, "unit": "", "tol": 0.005, "why": "3 × 2 × 2 = 12."}, {"q": "What happens before mitosis?", "opts": ["DNA is copied", "Chromosomes halve", "Gametes fuse"], "a": 0, "why": "DNA is copied"}], "exam": [{"q": "Describe how the cell cycle produces two genetically identical daughter cells.", "m": 3, "ms": ["DNA is replicated before division.", "Copies of each chromosome separate to opposite ends and nuclei divide.", "Cytoplasm and membrane divide, leaving identical chromosome sets."]}]}, {"id": "b-stem", "unit": "cells", "title": "Stem cells: benefits, risks and ethics", "spec": "4.1.2.3", "paper": [1], "tier": "all", "separate": false, "summary": "Stem cells are unspecialised cells that can divide and differentiate.", "notes": [{"title": "Understand the biology", "html": "<p>Stem cells are unspecialised cells that can divide and differentiate. Embryonic stem cells can form most human cell types; adult bone-marrow stem cells produce a more limited range, including blood cells. Plant meristems can produce different plant tissues throughout life.<\/p>"}, {"title": "Apply and explain", "html": "<p>Replacement cells may help damaged tissues, but infection and uncontrolled division are risks. Therapeutic cloning produces genetically matched cells, reducing rejection. Embryo use raises ethical objections. Meristems can rapidly clone rare plants or crops with desirable characteristics.<\/p>"}], "keypoints": ["Stem cells are unspecialised cells that can divide and differentiate.", "Replacement cells may help damaged tissues, but infection and uncontrolled division are risks."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Where are adult human stem cells found?", "opts": ["Mature red blood cells", "Bone marrow", "Tooth enamel"], "a": 1, "why": "Bone marrow"}, {"q": "Why use genetically matched stem cells?", "opts": ["To remove every protein", "To reduce rejection", "To prevent all cell division"], "a": 1, "why": "To reduce rejection"}], "exam": [{"q": "Evaluate embryonic stem cells for replacing damaged nerve tissue.", "m": 3, "ms": ["They can differentiate into a wider range of cell types than many adult stem cells.", "A biological risk such as infection or uncontrolled division must be considered.", "Potential treatment benefit must be weighed against ethical concerns about embryo use."]}]}, {"id": "b-diffusion", "unit": "cells", "title": "Diffusion and exchange surfaces", "spec": "4.1.3.1", "paper": [1], "tier": "all", "separate": false, "summary": "Diffusion is net movement down a concentration gradient.", "notes": [{"title": "Understand the biology", "html": "<p>Diffusion is net movement down a concentration gradient. Higher temperature, larger area and a steeper gradient usually increase its rate. Oxygen and carbon dioxide cross cell membranes by diffusion; the process itself requires no energy from respiration.<\/p>"}, {"title": "Apply and explain", "html": "<p>As size increases, surface area to volume ratio decreases. Large organisms need specialised exchange surfaces and transport systems. Alveoli and villi have large areas and short diffusion distances; blood flow and ventilation maintain gradients.<\/p>"}], "keypoints": ["Diffusion is net movement down a concentration gradient.", "As size increases, surface area to volume ratio decreases."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "A cube has side 2 cm. Express its surface area to volume ratio as x:1.", "a": 3, "unit": "", "tol": 0.005, "why": "Area 24 cm²; volume 8 cm³; 24:8 = 3:1."}, {"q": "Which change speeds diffusion?", "opts": ["A thicker barrier", "A smaller area", "A steeper gradient"], "a": 2, "why": "A steeper gradient"}], "exam": [{"q": "Explain why alveoli exchange gases rapidly.", "m": 3, "ms": ["Many alveoli provide a large surface area.", "Thin walls give a short diffusion distance.", "Ventilation and blood flow maintain concentration gradients."]}]}, {"id": "b-osmosis", "unit": "cells", "title": "Osmosis and percentage mass change", "spec": "4.1.3.2", "paper": [1], "tier": "all", "separate": false, "summary": "Osmosis is net water movement through a partially permeable membrane from a dilute solution to a more concentrated solution.", "notes": [{"title": "Understand the biology", "html": "<p>Osmosis is net water movement through a partially permeable membrane from a dilute solution to a more concentrated solution. Water moves both ways, but there is a net movement when concentrations differ. Water entry can make plant cells turgid.<\/p>"}, {"title": "Apply and explain", "html": "<p>Percentage mass change = (final − initial mass) ÷ initial mass × 100. Changing from 2.0 g to 2.3 g gives +15%; a negative value means loss. A graph crossing zero estimates a solution concentration causing no net water movement.<\/p>"}], "keypoints": ["Osmosis is net water movement through a partially permeable membrane from a dilute solution to a more concentrated solution.", "Percentage mass change = (final − initial mass) ÷ initial mass × 100."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "A cylinder changes from 4.0 g to 3.6 g. Calculate percentage mass change.", "a": -10, "unit": "%", "tol": 0.005, "why": "(3.6−4.0)/4.0 × 100 = −10%."}, {"q": "When does water enter a cell by osmosis?", "opts": ["Outside is more dilute than inside", "Outside is more concentrated", "Water cannot cross any membrane"], "a": 0, "why": "Outside is more dilute than inside"}], "exam": [{"q": "Explain why potato tissue loses mass in concentrated sugar solution.", "m": 3, "ms": ["The outside solution is more concentrated than the cell contents.", "Water moves out by osmosis across partially permeable cell membranes.", "Water loss reduces tissue mass."]}], "sim": "osmosis", "practical": {"title": "Required practical 3 · Osmosis in plant tissue", "method": ["Cut equal potato cylinders and record initial masses.", "Immerse in equal volumes of a concentration range for equal times.", "Remove, blot consistently and reweigh; repeat each concentration."], "variables": ["Independent: sugar or salt concentration.", "Dependent: percentage mass change.", "Control dimensions, tissue source, solution volume, temperature and time."], "safety": ["Use cutting equipment on a suitable surface under supervision.", "Do not eat laboratory samples."], "analysis": "Calculate percentage changes and means. Plot concentration against percentage change and interpolate the zero-change concentration, recognising scatter and measurement uncertainty."}}, {"id": "b-active", "unit": "cells", "title": "Active transport and comparing transport", "spec": "4.1.3.3", "paper": [1], "tier": "all", "separate": false, "summary": "Active transport moves substances against a concentration gradient, from lower to higher concentration.", "notes": [{"title": "Understand the biology", "html": "<p>Active transport moves substances against a concentration gradient, from lower to higher concentration. It requires energy from respiration. Root hairs absorb mineral ions from dilute soil solutions; intestinal cells can absorb sugars against their gradient.<\/p>"}, {"title": "Apply and explain", "html": "<p>Diffusion moves particles down a gradient; osmosis specifically describes water through a partially permeable membrane; active transport needs energy. Many mitochondria can support energy-demanding transport. The presence of a membrane alone does not prove osmosis: identify the substance moving.<\/p>"}], "keypoints": ["Active transport moves substances against a concentration gradient, from lower to higher concentration.", "Diffusion moves particles down a gradient; osmosis specifically describes water through a partially permeable membrane; active transport needs energy."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which process requires energy from respiration?", "opts": ["Osmosis", "Active transport", "Diffusion"], "a": 1, "why": "Active transport"}, {"q": "Mineral concentration is lower in soil than a root cell. Uptake uses…", "opts": ["Diffusion down the gradient", "Active transport", "Osmosis of ions"], "a": 1, "why": "Active transport"}], "exam": [{"q": "Explain why low oxygen availability can reduce mineral uptake by roots.", "m": 3, "ms": ["Less oxygen reduces aerobic respiration.", "Less energy is available for active transport.", "Mineral ions need to move against their concentration gradient."]}]}, {"id": "b-culture", "unit": "cells", "title": "Culturing bacteria and inhibition zones", "spec": "4.1.1.6", "paper": [1], "tier": "all", "separate": true, "summary": "Bacteria reproduce by binary fission.", "notes": [{"title": "Understand the biology", "html": "<p>Bacteria reproduce by binary fission. Sterile medium and equipment, brief lid opening and sterile inoculation reduce contamination. Incubating school cultures at 25°C reduces the risk of growing harmful human pathogens. Do not reopen incubated plates.<\/p>"}, {"title": "Apply and explain", "html": "<p>Equal discs carrying antiseptics can be compared using clear inhibition zones. Use area = πr² with radius half the diameter. Keep disc size, agar depth, bacterial species and incubation conditions constant. A clear zone indicates inhibited growth, not necessarily that every cell was killed.<\/p>"}, {"title": "Growth calculations", "html": "<p>If each bacterium divides once every 30 minutes under specified ideal conditions, a culture starting with 100 bacteria reaches 100 × 2⁴ = 1600 after two hours. Count the number of complete divisions before using powers of two. Real cultures eventually slow as resources fall and wastes accumulate.<\/p>"}], "keypoints": ["Bacteria reproduce by binary fission.", "Equal discs carrying antiseptics can be compared using clear inhibition zones."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "A clear circle has diameter 10 mm. Use π = 3.14 to calculate area.", "a": 78.5, "unit": "mm²", "tol": 0.005, "why": "Radius 5 mm; 3.14 × 25 = 78.5 mm²."}, {"q": "Why incubate school cultures at 25°C?", "opts": ["To sterilise agar", "Because no bacteria grow at 37°C", "To reduce harmful-pathogen risk"], "a": 2, "why": "To reduce harmful-pathogen risk"}], "exam": [{"q": "Explain three precautions in preparing a bacterial culture.", "m": 3, "ms": ["Sterilise medium and equipment to remove contaminants.", "Minimise lid opening to reduce airborne contamination.", "Secure without fully sealing the lid and incubate at 25°C to reduce risk."]}], "practical": {"title": "Required practical 2 · Antiseptics and bacterial growth", "method": ["Use teacher-approved cultures and aseptic technique to inoculate sterile agar evenly.", "Add equally sized discs with different antiseptics or concentrations and a solvent control.", "Secure the lid without fully sealing it; incubate at 25°C and measure zones without reopening."], "variables": ["Independent: antiseptic type or concentration, changing one at a time.", "Dependent: inhibition-zone area.", "Control species, agar depth, disc size, incubation time and temperature."], "safety": ["Use approved non-pathogenic organisms under supervision.", "Never open incubated plates; follow school disposal procedures."], "analysis": "Calculate πr² from measured diameters. State whether the disc area is included and apply the same rule consistently. Repeat independent plates and compare means."}}, {"id": "b-digestion", "unit": "organisation", "title": "Organisation and digestion", "spec": "4.2.1–4.2.2.1", "paper": [1], "tier": "all", "separate": false, "summary": "Similar cells form tissues, tissues form organs and organs cooperate in systems.", "notes": [{"title": "Understand the biology", "html": "<p>Similar cells form tissues, tissues form organs and organs cooperate in systems. Digestion changes large insoluble molecules into small soluble molecules. Villi provide a large absorbing area and a rich blood supply in the small intestine.<\/p>"}, {"title": "Apply and explain", "html": "<p>Amylase from salivary glands, pancreas and small intestine breaks starch into sugars. Proteases from stomach, pancreas and small intestine produce amino acids. Lipases from pancreas and small intestine produce glycerol and fatty acids. Liver-made bile is stored in the gall bladder, neutralises acid and emulsifies fat; it is not an enzyme.<\/p>"}], "keypoints": ["Similar cells form tissues, tissues form organs and organs cooperate in systems.", "Amylase from salivary glands, pancreas and small intestine breaks starch into sugars."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Protein digestion produces…", "opts": ["Amino acids", "Starch", "Only fatty acids"], "a": 0, "why": "Amino acids"}, {"q": "Where is bile made?", "opts": ["Liver", "Gall bladder", "Stomach"], "a": 0, "why": "Liver"}], "exam": [{"q": "Explain how bile assists fat digestion.", "m": 3, "ms": ["It neutralises acid, providing alkaline conditions for lipase.", "It emulsifies fat into smaller droplets.", "This increases surface area available to lipase."]}]}, {"id": "b-enzymes", "unit": "organisation", "title": "Enzymes, temperature and pH", "spec": "4.2.2.1", "paper": [1], "tier": "all", "separate": false, "summary": "Enzymes are biological catalysts, usually proteins.", "notes": [{"title": "Understand the biology", "html": "<p>Enzymes are biological catalysts, usually proteins. A substrate fits an active site, products are released and the enzyme can be reused. The lock-and-key model explains specificity but is simplified. Catalysts speed reactions without being used up.<\/p>"}, {"title": "Apply and explain", "html": "<p>Warming initially increases collisions and rate. Above an optimum, active-site shape changes and enzymes denature; extreme pH can do the same. Cold normally slows activity without denaturing. For disappearance of a fixed substrate amount, compare relative rate using 1/time.<\/p>"}], "keypoints": ["Enzymes are biological catalysts, usually proteins.", "Warming initially increases collisions and rate."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Starch digestion takes 25 s. Calculate 1/time.", "a": 0.04, "unit": "s⁻¹", "tol": 0.005, "why": "1/25 = 0.04 s⁻¹."}, {"q": "Why is a denatured enzyme less effective?", "opts": ["It creates extra oxygen", "Its active site no longer fits the substrate", "It becomes starch"], "a": 1, "why": "Its active site no longer fits the substrate"}], "exam": [{"q": "Explain why an enzyme works well at 37°C but poorly at 70°C.", "m": 3, "ms": ["High temperature alters protein structure.", "The active site changes shape / denatures.", "Fewer substrate molecules fit, so fewer enzyme–substrate complexes form."]}], "sim": "enzyme", "practical": {"title": "Required practical 5 · pH and amylase", "method": ["Equilibrate amylase, starch and buffer at a chosen water-bath temperature.", "Mix measured volumes and sample onto iodine every 30 seconds.", "Record when iodine no longer turns blue-black; repeat at a range of pH values."], "variables": ["Independent: pH using buffers.", "Dependent: time until starch is undetectable, or 1/time.", "Control temperature, concentrations, volumes and sampling interval."], "safety": ["Wear eye protection and avoid iodine contact.", "Use school-approved amylase rather than saliva."], "analysis": "Plot mean relative rate against pH. The endpoint lies between the last positive and first negative sample, limiting time resolution to the sampling interval."}}, {"id": "b-foodtests", "unit": "organisation", "title": "Food tests and controls", "spec": "4.2.2.1", "paper": [1], "tier": "all", "separate": false, "summary": "Iodine turns blue-black with starch.", "notes": [{"title": "Understand the biology", "html": "<p>Iodine turns blue-black with starch. Heated Benedict’s reagent gives a green to brick-red precipitate with reducing sugars. Biuret turns lilac with protein. Sudan III stains a lipid layer red. Use the correct test conditions; reagent colour alone without the method may mislead.<\/p>"}, {"title": "Apply and explain", "html": "<p>Use clean separate tubes and droppers, standardised volumes and equal heating time. A known positive checks that the test works; water is a negative control. A negative result means none was detected under those conditions, not proof that absolutely none exists.<\/p>"}], "keypoints": ["Iodine turns blue-black with starch.", "Use clean separate tubes and droppers, standardised volumes and equal heating time."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which indicates protein?", "opts": ["Orange iodine", "Blue Benedict’s after heating", "Lilac Biuret result"], "a": 2, "why": "Lilac Biuret result"}, {"q": "Which test requires a hot water bath?", "opts": ["Iodine", "A ruler measurement", "Benedict’s"], "a": 2, "why": "Benedict’s"}], "exam": [{"q": "A food turns iodine blue-black but heated Benedict’s stays blue. Interpret the results and name a useful control.", "m": 3, "ms": ["Starch is detected.", "Reducing sugar is not detected under the conditions.", "A known sugar solution checks the Benedict’s reagent and heating."]}], "practical": {"title": "Required practical 4 · Food tests", "method": ["Prepare similar food suspensions in separate labelled tubes.", "Test starch with iodine, reducing sugars with heated Benedict’s and protein with Biuret.", "Use the school-approved lipid test, such as Sudan III, and record known positive and water controls."], "variables": ["Standardise food mass, solvent volume and reagent volumes.", "Control heating duration for Benedict’s comparisons."], "safety": ["Wear eye protection for reagents.", "Handle hot water baths carefully and never taste samples."], "analysis": "Record observations separately from conclusions. Negative tests need working positive controls before interpretation."}}, {"id": "b-heart", "unit": "organisation", "title": "Heart, vessels and gas exchange", "spec": "4.2.2.2", "paper": [1], "tier": "all", "separate": false, "summary": "The right ventricle pumps through the pulmonary artery to lungs; pulmonary veins return blood to the left side.", "notes": [{"title": "Understand the biology", "html": "<p>The right ventricle pumps through the pulmonary artery to lungs; pulmonary veins return blood to the left side. The left ventricle pumps through the aorta to the body; venae cavae return blood. Coronary arteries supply heart muscle. Valves reduce backflow and a right-atrial pacemaker coordinates rate.<\/p>"}, {"title": "Apply and explain", "html": "<p>Arteries carry blood away under pressure and have muscular elastic walls. Veins return blood at lower pressure and have valves; thin capillaries permit exchange. Air travels through trachea and bronchi to alveoli, whose large area, thin walls and capillary supply support diffusion.<\/p>"}], "keypoints": ["The right ventricle pumps through the pulmonary artery to lungs; pulmonary veins return blood to the left side.", "Arteries carry blood away under pressure and have muscular elastic walls."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which vessel carries blood to lungs?", "opts": ["Pulmonary artery", "Pulmonary vein", "Aorta"], "a": 0, "why": "Pulmonary artery"}, {"q": "70 cm³ per beat at 80 beats/min gives what flow?", "a": 5600, "unit": "cm³/min", "tol": 0.005, "why": "70 × 80 = 5600."}], "exam": [{"q": "Explain why the left ventricle has a thicker muscular wall than the right.", "m": 3, "ms": ["It pumps blood around the whole body.", "It must generate a higher pressure.", "More muscle produces a greater force of contraction."]}]}, {"id": "b-blood", "unit": "organisation", "title": "Blood and cardiovascular treatments", "spec": "4.2.2.3–4.2.2.4", "paper": [1], "tier": "all", "separate": false, "summary": "Plasma transports dissolved materials including glucose, urea and carbon dioxide.", "notes": [{"title": "Understand the biology", "html": "<p>Plasma transports dissolved materials including glucose, urea and carbon dioxide. Red cells carry oxygen using haemoglobin and have a biconcave shape and no nucleus. White cells defend against pathogens; platelets help clot blood and reduce blood loss.<\/p>"}, {"title": "Apply and explain", "html": "<p>Fatty deposits narrow coronary arteries, reducing oxygen supply to heart muscle. Stents hold arteries open; statins reduce blood cholesterol. Replacement valves, pacemakers, donor hearts and temporary artificial hearts address different problems. Compare benefits with procedure risks, side effects and donor availability.<\/p>"}], "keypoints": ["Plasma transports dissolved materials including glucose, urea and carbon dioxide.", "Fatty deposits narrow coronary arteries, reducing oxygen supply to heart muscle."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which component helps clot blood?", "opts": ["Red cells", "Platelets", "Glucose"], "a": 1, "why": "Platelets"}, {"q": "What does a coronary stent do?", "opts": ["Replaces every valve", "Keeps a narrowed artery open", "Makes insulin"], "a": 1, "why": "Keeps a narrowed artery open"}], "exam": [{"q": "Give a benefit and limitation of a stent and explain why coronary flow matters.", "m": 3, "ms": ["A stent improves blood flow through a narrowed artery.", "Surgery, infection or clotting presents a risk.", "Heart muscle receives more oxygen for aerobic respiration."]}]}, {"id": "b-health", "unit": "organisation", "title": "Health, risk factors and cancer", "spec": "4.2.2.5–4.2.2.7", "paper": [1], "tier": "all", "separate": false, "summary": "Health includes physical and mental wellbeing.", "notes": [{"title": "Understand the biology", "html": "<p>Health includes physical and mental wellbeing. Communicable diseases spread between organisms; non-communicable ones do not. Risk factors increase probability, not certainty. Smoking increases lung disease risk; obesity increases type 2 diabetes risk; heavy alcohol use can damage liver tissue.<\/p>"}, {"title": "Apply and explain", "html": "<p>Correlation alone does not establish causation: age, diet or other confounders may explain an association. Cancer involves uncontrolled division. Benign tumours stay local; malignant tumours invade and can spread to form secondary tumours. Environmental exposure and inherited factors can both influence risk.<\/p>"}], "keypoints": ["Health includes physical and mental wellbeing.", "Correlation alone does not establish causation: age, diet or other confounders may explain an association."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "A risk factor…", "opts": ["Guarantees disease", "Must always be inherited", "Increases disease probability"], "a": 2, "why": "Increases disease probability"}, {"q": "A malignant tumour can…", "opts": ["Never divide", "Only cause an infectious disease", "Invade tissues and spread"], "a": 2, "why": "Invade tissues and spread"}], "exam": [{"q": "Why does a survey linking low exercise and heart disease not prove causation?", "m": 3, "ms": ["Correlation alone does not establish cause.", "A confounding factor such as age or smoking may affect both.", "Further evidence with appropriate comparisons / controls is needed."]}]}, {"id": "b-plants", "unit": "organisation", "title": "Plant tissues and transport", "spec": "4.2.3.1–4.2.3.2", "paper": [1], "tier": "all", "separate": false, "summary": "Palisade cells contain many chloroplasts; spongy mesophyll has air spaces.", "notes": [{"title": "Understand the biology", "html": "<p>Palisade cells contain many chloroplasts; spongy mesophyll has air spaces. Guard cells control stomata. Dead hollow lignified xylem carries water and mineral ions; living phloem translocates dissolved sugars from sources to tissues using or storing them.<\/p>"}, {"title": "Apply and explain", "html": "<p>Evaporation from leaf cells and diffusion through stomata drive transpiration. Replacement water moves up xylem from roots. Wind and warmth often increase loss; humidity reduces the water-vapour gradient. A potometer estimates water uptake, which differs slightly from transpiration because plants use some water.<\/p>"}], "keypoints": ["Palisade cells contain many chloroplasts; spongy mesophyll has air spaces.", "Evaporation from leaf cells and diffusion through stomata drive transpiration."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which tissue transports sugars?", "opts": ["Phloem", "Xylem", "Epidermis only"], "a": 0, "why": "Phloem"}, {"q": "Why does high humidity reduce transpiration?", "opts": ["It reduces the water-vapour gradient", "It removes all stomata", "It turns xylem into phloem"], "a": 0, "why": "It reduces the water-vapour gradient"}], "exam": [{"q": "Explain why wind can increase water uptake by a leafy shoot.", "m": 3, "ms": ["Wind removes humid air near the leaf.", "The steeper gradient increases water-vapour diffusion / transpiration.", "Water lost from leaves is replaced through the xylem."]}]}, {"id": "b-pathogens", "unit": "infection", "title": "Pathogens and named diseases", "spec": "4.3.1.1–4.3.1.5", "paper": [1], "tier": "all", "separate": false, "summary": "Viruses reproduce inside host cells; bacteria can multiply and produce toxins.", "notes": [{"title": "Understand the biology", "html": "<p>Viruses reproduce inside host cells; bacteria can multiply and produce toxins. Measles spreads in droplets, causing fever and rash; HIV damages immune cells and can lead to AIDS. Tobacco mosaic virus causes discoloured leaf areas and reduces photosynthesis.<\/p>"}, {"title": "Apply and explain", "html": "<p>Salmonella causes food poisoning: hygiene and poultry vaccination reduce transmission. Gonorrhoea is bacterial and sexually transmitted. Rose black spot is fungal. Malaria is caused by a protist carried by mosquitoes: nets and removal of breeding sites reduce transmission.<\/p>"}], "keypoints": ["Viruses reproduce inside host cells; bacteria can multiply and produce toxins.", "Salmonella causes food poisoning: hygiene and poultry vaccination reduce transmission."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "What causes malaria?", "opts": ["A fungus", "A protist", "The mosquito itself as a bacterium"], "a": 1, "why": "A protist"}, {"q": "Why can TMV reduce growth?", "opts": ["It makes animal hormones", "Leaf damage reduces photosynthesis", "It creates extra chlorophyll"], "a": 1, "why": "Leaf damage reduces photosynthesis"}], "exam": [{"q": "Explain how mosquito nets and removing standing water reduce malaria spread.", "m": 3, "ms": ["Nets reduce mosquito bites.", "Removing standing water reduces mosquito breeding.", "Fewer bites by infected mosquitoes reduce protist transmission."]}]}, {"id": "b-defence", "unit": "infection", "title": "Human defences and vaccination", "spec": "4.3.1.6–4.3.1.7", "paper": [1], "tier": "all", "separate": false, "summary": "Skin forms a barrier and clots close wounds.", "notes": [{"title": "Understand the biology", "html": "<p>Skin forms a barrier and clots close wounds. Nose hairs and mucus trap particles; airway cilia move mucus towards the throat. Stomach acid kills many swallowed pathogens. White cells engulf pathogens, make specific antibodies and produce antitoxins.<\/p>"}, {"title": "Apply and explain", "html": "<p>Vaccines present harmless pathogen antigens and stimulate an immune response. Later exposure triggers faster specific antibody production, often preventing serious illness. High uptake reduces transmission and can protect vulnerable people. Compare rates in comparable populations rather than raw case totals.<\/p>"}], "keypoints": ["Skin forms a barrier and clots close wounds.", "Vaccines present harmless pathogen antigens and stimulate an immune response."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "What neutralises bacterial toxins?", "opts": ["Red-cell nuclei", "Insulin", "Antitoxins"], "a": 2, "why": "Antitoxins"}, {"q": "Why does vaccination help on later exposure?", "opts": ["All antibiotics become unnecessary", "It guarantees no transmission ever", "A faster specific immune response occurs"], "a": 2, "why": "A faster specific immune response occurs"}], "exam": [{"q": "Explain how vaccination can prevent later disease.", "m": 3, "ms": ["Pathogen antigens stimulate a primary immune response safely.", "Later exposure triggers faster production of specific antibodies.", "The pathogen is destroyed before serious illness develops."]}]}, {"id": "b-drugs", "unit": "infection", "title": "Antibiotics and developing medicines", "spec": "4.3.1.8–4.3.1.9", "paper": [1], "tier": "all", "separate": false, "summary": "Antibiotics act on bacteria, not viruses reproducing inside cells.", "notes": [{"title": "Understand the biology", "html": "<p>Antibiotics act on bacteria, not viruses reproducing inside cells. Painkillers relieve symptoms without necessarily destroying pathogens. Penicillin came from mould; aspirin developed from willow chemistry and digitalis from foxgloves. Resistant strains make suitable prescribing important.<\/p>"}, {"title": "Apply and explain", "html": "<p>Preclinical tests use cells, tissues and animals. Low-dose healthy-volunteer trials examine safety before patient trials assess efficacy and dose. Random allocation and double-blind comparisons reduce bias; a placebo is useful where ethical. Sufficient sample size and peer review strengthen conclusions.<\/p>"}], "keypoints": ["Antibiotics act on bacteria, not viruses reproducing inside cells.", "Preclinical tests use cells, tissues and animals."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Why do antibiotics not treat viral infections?", "opts": ["Viruses lack the bacterial targets and reproduce inside host cells", "Viruses are bigger than all bacteria", "Antibiotics only act on plants"], "a": 0, "why": "Viruses lack the bacterial targets and reproduce inside host cells"}, {"q": "Double-blind means…", "opts": ["Neither participants nor assessors know treatment allocation", "Only participants know", "Everyone receives two drugs"], "a": 0, "why": "Neither participants nor assessors know treatment allocation"}], "exam": [{"q": "Explain three ways to improve the validity of a drug trial.", "m": 3, "ms": ["Random allocation reduces systematic group differences.", "An appropriate comparison group helps identify the treatment effect.", "Blinding reduces expectation and observer bias."]}]}, {"id": "b-monoclonal", "unit": "infection", "title": "Monoclonal antibodies", "spec": "4.3.2", "paper": [1], "tier": "higher", "separate": true, "summary": "Monoclonal antibodies bind one particular antigen.", "notes": [{"title": "Understand the biology", "html": "<p>Monoclonal antibodies bind one particular antigen. Antibody-producing lymphocytes from an exposed mouse are fused with tumour cells to form hybridomas. A selected hybridoma is cloned and grown, combining antibody specificity with repeated division.<\/p>"}, {"title": "Apply and explain", "html": "<p>Pregnancy tests detect hCG using antibodies. Labelled antibodies locate molecules or disease markers; attached drugs can target cancer cells. Targeting may reduce healthy-tissue damage, but side effects, cost and uncertain effectiveness still matter.<\/p>"}], "keypoints": ["Monoclonal antibodies bind one particular antigen.", "Pregnancy tests detect hCG using antibodies."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Why use a hybridoma?", "opts": ["It is a bacterium without DNA", "It combines antibody production and repeated division", "It makes every antigen"], "a": 1, "why": "It combines antibody production and repeated division"}, {"q": "What makes targeted binding possible?", "opts": ["Absence of proteins", "Antibody specificity for an antigen", "Equal binding to every molecule"], "a": 1, "why": "Antibody specificity for an antigen"}], "exam": [{"q": "Explain how a drug attached to a monoclonal antibody can target cancer cells.", "m": 3, "ms": ["The antibody recognises an antigen on target cells.", "An attached drug is delivered with the antibody.", "This can concentrate treatment at target cells and reduce healthy-tissue exposure."]}]}, {"id": "b-plantdefence", "unit": "infection", "title": "Plant disease and defence", "spec": "4.3.3", "paper": [1], "tier": "all", "separate": true, "summary": "Stunting, spots, decay and discolouration can indicate disease, but symptoms may have other causes.", "notes": [{"title": "Understand the biology", "html": "<p>Stunting, spots, decay and discolouration can indicate disease, but symptoms may have other causes. Manuals, laboratories and antibody-based tests aid diagnosis. Nitrate deficiency stunts growth through reduced protein synthesis; magnesium deficiency causes chlorosis through reduced chlorophyll. Aphids are pests rather than pathogens.<\/p>"}, {"title": "Apply and explain", "html": "<p>Cell walls, waxy cuticles and bark provide physical barriers. Plants may shed infected leaves or make antibacterial chemicals and poisons. Thorns and hairs deter herbivores. Link each defence to its threat; plants do not produce human white blood cells.<\/p>"}], "keypoints": ["Stunting, spots, decay and discolouration can indicate disease, but symptoms may have other causes.", "Cell walls, waxy cuticles and bark provide physical barriers."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which deficiency reduces chlorophyll?", "opts": ["Nitrate only", "Oxygen", "Magnesium"], "a": 2, "why": "Magnesium"}, {"q": "Which is a physical plant defence?", "opts": ["Insulin", "White blood cells", "Waxy cuticle"], "a": 2, "why": "Waxy cuticle"}], "exam": [{"q": "Explain why yellow leaves do not prove infection and suggest an alternative explanation and investigation.", "m": 3, "ms": ["The symptom is not specific to a pathogen.", "Magnesium deficiency can cause reduced chlorophyll / chlorosis.", "Use diagnostic testing or a controlled nutrient comparison."]}]}, {"id": "b-photo", "unit": "bioenergetics", "title": "Photosynthesis and glucose uses", "spec": "4.4.1.1, 4.4.1.3", "paper": [1], "tier": "all", "separate": false, "summary": "Photosynthesis transfers light energy to chemical stores: carbon dioxide + water → glucose + oxygen.", "notes": [{"title": "Understand the biology", "html": "<p>Photosynthesis transfers light energy to chemical stores: carbon dioxide + water → glucose + oxygen. Chlorophyll absorbs light and the process is endothermic. Recognise CO₂, H₂O, C₆H₁₂O₆ and O₂. Plants respire continuously; photosynthesis needs light.<\/p>"}, {"title": "Apply and explain", "html": "<p>Glucose supplies respiration and can become starch, oils or cellulose. Nitrate ions supply nitrogen for amino acid and protein synthesis. Insoluble starch is useful for storage because it has little direct osmotic effect compared with an equivalent number of dissolved sugar molecules.<\/p>"}], "keypoints": ["Photosynthesis transfers light energy to chemical stores: carbon dioxide + water → glucose + oxygen.", "Glucose supplies respiration and can become starch, oils or cellulose."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which gas enters for photosynthesis?", "opts": ["Carbon dioxide", "Oxygen only", "Nitrogen gas directly"], "a": 0, "why": "Carbon dioxide"}, {"q": "Why are nitrates needed?", "opts": ["For amino acid and protein synthesis", "To prevent all respiration", "To turn leaves into roots"], "a": 0, "why": "For amino acid and protein synthesis"}], "exam": [{"q": "Explain three uses of glucose in a growing plant.", "m": 3, "ms": ["Respiration transfers energy for cellular processes.", "Cellulose forms cell walls.", "Starch or oils store material, or amino acids are made with nitrate-derived nitrogen."]}]}, {"id": "b-photo-rate", "unit": "bioenergetics", "title": "Photosynthesis rate and pondweed", "spec": "4.4.1.2", "paper": [1], "tier": "all", "separate": false, "summary": "Light, carbon dioxide, temperature and chlorophyll amount affect photosynthesis.", "notes": [{"title": "Understand the biology", "html": "<p>Light, carbon dioxide, temperature and chlorophyll amount affect photosynthesis. At low light, increasing intensity often raises oxygen production. A horizontal curve shows constant rate rather than no photosynthesis; interpret what the axes actually measure.<\/p>"}, {"title": "Apply and explain", "html": "<p>Compare oxygen per unit time while controlling plant species and size, carbon dioxide and temperature. Allow equilibration and repeat. Bubble counting is convenient but unequal bubble volumes limit accuracy; gas collection measures volume more directly.<\/p>"}], "keypoints": ["Light, carbon dioxide, temperature and chlorophyll amount affect photosynthesis.", "Compare oxygen per unit time while controlling plant species and size, carbon dioxide and temperature."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "18 cm³ oxygen is collected in 6 minutes. Calculate rate.", "a": 3, "unit": "cm³/min", "tol": 0.005, "why": "18/6 = 3."}, {"q": "What does a horizontal oxygen-rate curve indicate?", "opts": ["No respiration", "A constant rate", "No photosynthesis"], "a": 1, "why": "A constant rate"}], "exam": [{"q": "Suggest three improvements to a pondweed experiment comparing light levels.", "m": 3, "ms": ["Control temperature to avoid lamp heating as a confounder.", "Keep plant size and carbon dioxide supply consistent.", "Collect gas volume over equal periods and repeat for means."]}], "sim": "photosynthesis", "practical": {"title": "Required practical 6 · Light intensity and photosynthesis", "method": ["Place pondweed in bicarbonate solution and arrange oxygen collection.", "Change lamp distance or measured intensity, allowing equilibration.", "Measure oxygen over a fixed period, repeat and calculate mean rates."], "variables": ["Independent: lamp distance or measured intensity.", "Dependent: gas volume per time, or bubble count with its limitation.", "Control temperature, carbon dioxide, species and plant size."], "safety": ["Keep electricity away from water.", "Handle glass and cutting tools carefully; a cool LED reduces heating."], "analysis": "Bubble sizes vary, so gas volume is generally a better measure. Control heating separately from light; net oxygen production is influenced by respiration as well as photosynthesis."}}, {"id": "b-photo-higher", "unit": "bioenergetics", "title": "Limiting factors and greenhouse economics", "spec": "4.4.1.2 (HT)", "paper": [1], "tier": "higher", "separate": false, "summary": "A limiting factor prevents further increase in photosynthesis under the current conditions.", "notes": [{"title": "Understand the biology", "html": "<p>A limiting factor prevents further increase in photosynthesis under the current conditions. If extra carbon dioxide raises a plateau, carbon dioxide was limiting there. A different point may be limited by light or temperature; compare curves rather than assigning one universal limiting factor.<\/p>"}, {"title": "Apply and explain", "html": "<p>In the point-source model, light intensity is proportional to 1/distance². Doubling distance quarters intensity. Greenhouse heating, lighting and carbon dioxide can increase yield only when useful; compare extra crop revenue against running costs to assess profit.<\/p>"}], "keypoints": ["A limiting factor prevents further increase in photosynthesis under the current conditions.", "In the point-source model, light intensity is proportional to 1/distance²."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Intensity is 80 units at 10 cm. Estimate intensity at 20 cm.", "a": 20, "unit": "units", "tol": 0.005, "why": "Distance doubles, so intensity divides by 4."}, {"q": "Revenue rises £600 and costs rise £750. Profit changes by…", "opts": ["A £150 increase", "A £1350 increase", "A £150 decrease"], "a": 2, "why": "A £150 decrease"}], "exam": [{"q": "Extra light has no effect but extra carbon dioxide raises rate. Explain and give an economic implication.", "m": 3, "ms": ["Light is not limiting under the tested conditions.", "Carbon dioxide is limiting because adding it raises rate.", "Extra lighting alone adds cost without improving production."]}]}, {"id": "b-respiration", "unit": "bioenergetics", "title": "Aerobic and anaerobic respiration", "spec": "4.4.2.1", "paper": [1], "tier": "all", "separate": false, "summary": "Respiration is an exothermic cellular process supplying energy for movement, synthesis and keeping warm.", "notes": [{"title": "Understand the biology", "html": "<p>Respiration is an exothermic cellular process supplying energy for movement, synthesis and keeping warm. Aerobic respiration uses glucose and oxygen and produces carbon dioxide and water. Breathing moves air; it is not respiration. Both plants and animals respire.<\/p>"}, {"title": "Apply and explain", "html": "<p>Muscles respiring anaerobically form lactic acid and transfer less energy per glucose because breakdown is incomplete. Yeast and plant cells can produce ethanol and carbon dioxide anaerobically. Fermentation supplies carbon dioxide to raise bread dough and ethanol for alcoholic drinks.<\/p>"}], "keypoints": ["Respiration is an exothermic cellular process supplying energy for movement, synthesis and keeping warm.", "Muscles respiring anaerobically form lactic acid and transfer less energy per glucose because breakdown is incomplete."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Aerobic respiration produces…", "opts": ["Carbon dioxide and water", "Glucose and oxygen", "Ethanol and oxygen"], "a": 0, "why": "Carbon dioxide and water"}, {"q": "Why is less energy transferred anaerobically?", "opts": ["Glucose breakdown is incomplete", "Extra oxygen is made", "No living cells are involved"], "a": 0, "why": "Glucose breakdown is incomplete"}], "exam": [{"q": "Compare anaerobic respiration in muscles and yeast.", "m": 3, "ms": ["Both break down glucose without oxygen.", "Muscles produce lactic acid; yeast produces ethanol and carbon dioxide.", "Both transfer less energy per glucose than aerobic respiration."]}]}, {"id": "b-exercise", "unit": "bioenergetics", "title": "Exercise responses and metabolism", "spec": "4.4.2.2–4.4.2.3", "paper": [1], "tier": "all", "separate": false, "summary": "Exercise raises muscular energy demand.", "notes": [{"title": "Understand the biology", "html": "<p>Exercise raises muscular energy demand. Heart rate, breathing rate and breath volume increase, supplying oxygen and glucose and removing carbon dioxide. Insufficient oxygen leads to additional anaerobic respiration and lactic acid accumulation, contributing to fatigue.<\/p>"}, {"title": "Apply and explain", "html": "<p>Metabolism is all reactions in cells or an organism: respiration, making carbohydrates from glucose, lipids from glycerol and fatty acids, and proteins from amino acids. Excess amino acids are broken down to form urea. Plants need nitrate ions when synthesising amino acids.<\/p>"}], "keypoints": ["Exercise raises muscular energy demand.", "Metabolism is all reactions in cells or an organism: respiration, making carbohydrates from glucose, lipids from glycerol and fatty acids, and proteins from amino acids."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Why does heart rate rise in exercise?", "opts": ["To turn oxygen into lactic acid", "To deliver oxygen and glucose faster", "To stop muscle blood flow"], "a": 1, "why": "To deliver oxygen and glucose faster"}, {"q": "Metabolism means…", "opts": ["Only stomach digestion", "All reactions in a cell or organism", "Only breathing"], "a": 1, "why": "All reactions in a cell or organism"}], "exam": [{"q": "Explain why heart rate and breathing rate increase during exercise.", "m": 3, "ms": ["Muscle energy demand / respiration increases.", "Faster breathing supplies oxygen and removes carbon dioxide.", "Faster circulation delivers oxygen and glucose to muscles."]}]}, {"id": "b-debt", "unit": "bioenergetics", "title": "Lactic acid and oxygen debt", "spec": "4.4.2.2 (HT)", "paper": [1], "tier": "higher", "separate": false, "summary": "After intense exercise, blood carries lactic acid from muscles to the liver, where it is converted back to glucose.", "notes": [{"title": "Understand the biology", "html": "<p>After intense exercise, blood carries lactic acid from muscles to the liver, where it is converted back to glucose. The extra oxygen needed during recovery to remove accumulated lactic acid is called oxygen debt in the GCSE model.<\/p>"}, {"title": "Apply and explain", "html": "<p>An oxygen-uptake trace returns gradually towards resting levels. Compare recovery uptake with the resting baseline rather than counting all oxygen breathed. An extra 1.5 litres each minute over four minutes totals six litres in a simplified constant-rate example.<\/p>"}], "keypoints": ["After intense exercise, blood carries lactic acid from muscles to the liver, where it is converted back to glucose.", "An oxygen-uptake trace returns gradually towards resting levels."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Additional uptake averages 2 L/min for 3 min. Calculate extra oxygen.", "a": 6, "unit": "L", "tol": 0.005, "why": "2 × 3 = 6."}, {"q": "Where is lactic acid converted back to glucose?", "opts": ["Alveoli", "Bladder", "Liver"], "a": 2, "why": "Liver"}], "exam": [{"q": "Explain elevated oxygen uptake after intense exercise.", "m": 3, "ms": ["Anaerobic respiration has caused lactic acid accumulation.", "Blood carries it to the liver for conversion back to glucose.", "Extra oxygen is needed during recovery, forming oxygen debt."]}]}, {"id": "b-nerves", "unit": "homeostasis", "title": "Homeostasis, neurones and reflexes", "spec": "4.5.1–4.5.2.1", "paper": [2], "tier": "all", "separate": false, "summary": "Homeostasis maintains suitable internal conditions for cells, including temperature, glucose and water levels.", "notes": [{"title": "Understand the biology", "html": "<p>Homeostasis maintains suitable internal conditions for cells, including temperature, glucose and water levels. Receptors detect stimuli, coordination centres process information and effectors respond. The CNS is the brain and spinal cord; electrical impulses travel along neurones.<\/p>"}, {"title": "Apply and explain", "html": "<p>A reflex pathway includes receptor, sensory neurone, relay neurone, motor neurone and effector. Chemical transmitters cross synapses. Reflexes are rapid and automatic without conscious decision-making, protecting against damage. The brain can receive information without initiating the first protective response.<\/p>"}], "keypoints": ["Homeostasis maintains suitable internal conditions for cells, including temperature, glucose and water levels.", "A reflex pathway includes receptor, sensory neurone, relay neurone, motor neurone and effector."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which neurone carries information towards the CNS?", "opts": ["Sensory", "Motor", "A red blood cell"], "a": 0, "why": "Sensory"}, {"q": "An effector is…", "opts": ["A muscle or gland producing a response", "Only a receptor", "The stimulus itself"], "a": 0, "why": "A muscle or gland producing a response"}], "exam": [{"q": "Describe withdrawal of a hand from a hot object.", "m": 3, "ms": ["A receptor detects the stimulus and a sensory neurone carries an impulse to the CNS.", "Signals pass across synapses via a relay neurone to a motor neurone.", "A muscle contracts to withdraw the hand."]}]}, {"id": "b-reaction", "unit": "homeostasis", "title": "Investigating reaction time", "spec": "4.5.2.1", "paper": [2], "tier": "all", "separate": false, "summary": "A falling ruler caught by a participant provides a distance used to estimate reaction time through a conversion table.", "notes": [{"title": "Understand the biology", "html": "<p>A falling ruler caught by a participant provides a distance used to estimate reaction time through a conversion table. Investigate a safe factor such as distraction or practice. Obtain consent, permit withdrawal and do not administer medication or deprive participants of sleep.<\/p>"}, {"title": "Apply and explain", "html": "<p>Keep the start position, catching hand and release procedure constant. Randomise condition order to reduce practice effects; repeat across participants. Distance is not time, so report units honestly and use a suitable conversion before quoting seconds.<\/p>"}], "keypoints": ["A falling ruler caught by a participant provides a distance used to estimate reaction time through a conversion table.", "Keep the start position, catching hand and release procedure constant."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Fall distances are 12, 14 and 16 cm. Calculate the mean.", "a": 14, "unit": "cm", "tol": 0.005, "why": "42/3 = 14."}, {"q": "Which reduces order bias?", "opts": ["Deleting slow trials", "Randomising condition order", "Always testing distraction last"], "a": 1, "why": "Randomising condition order"}], "exam": [{"q": "Explain three controls in a ruler-drop comparison of distraction.", "m": 3, "ms": ["Use consistent hand and ruler starting positions.", "Randomise or counterbalance condition order.", "Repeat trials across participants and compare means."]}], "practical": {"title": "Required practical 7 · Human reaction time", "method": ["Obtain consent and explain a safe comparison such as distraction.", "Drop a ruler unexpectedly from a consistent start while a participant catches it.", "Record distance, repeat in randomised condition order and use a conversion table if quoting time."], "variables": ["Independent: selected safe factor.", "Dependent: fall distance or converted time.", "Control catching hand, posture, ruler position and instructions."], "safety": ["Allow participants to withdraw.", "Do not administer stimulants or medication or deliberately deprive sleep."], "analysis": "Compare repeated participant means. Record unusual values and investigate rather than deleting results solely because they disagree with a prediction."}}, {"id": "b-brain", "unit": "homeostasis", "title": "Brain regions and their roles", "spec": "4.5.2.2", "paper": [2], "tier": "all", "separate": true, "summary": "The cerebral cortex supports conscious thought, memory and language.", "notes": [{"title": "Understand the biology", "html": "<p>The cerebral cortex supports conscious thought, memory and language. The cerebellum coordinates movement and balance; the medulla controls automatic functions such as breathing and heart rate. Regions are highly interconnected rather than isolated units.<\/p>"}, {"title": "Identify regions on a diagram", "html": "<p>Locate the large folded cerebral cortex, the smaller cerebellum towards the back, and the medulla in the brainstem. Associate each region with its main functions. A labelled diagram is a model of a complex organ; use landmarks and relative positions rather than relying only on colours.<\/p>"}], "keypoints": ["The cerebral cortex supports conscious thought, memory and language.", "Link a symptom to a relevant function but avoid diagnosing solely from it."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which region coordinates balance?", "opts": ["Medulla", "Cornea", "Cerebellum"], "a": 2, "why": "Cerebellum"}, {"q": "Which helps control heart rate?", "opts": ["Retina", "Cerebellum only", "Medulla"], "a": 2, "why": "Medulla"}], "exam": [{"q": "State the main functions of the cerebral cortex, cerebellum and medulla.", "m": 3, "ms": ["Cerebral cortex: conscious thought, intelligence, memory or language.", "Cerebellum: coordination of movement or balance.", "Medulla: automatic functions such as breathing or heart rate."]}]}, {"id": "b-brain-research", "unit": "homeostasis", "title": "Investigating brain function", "spec": "4.5.2.2 (HT)", "paper": [2], "tier": "higher", "separate": true, "summary": "Brain mapping uses observations of patients with damage, electrical stimulation and MRI.", "notes": [{"title": "Understand the biology", "html": "<p>Brain mapping uses observations of patients with damage, electrical stimulation and MRI. Each provides different evidence: scans show structures and patient observations link damage to function. Electrical stimulation can reveal a response when a region is activated.<\/p>"}, {"title": "Apply and explain", "html": "<p>Complex connections make cause and effect difficult to isolate. Brain tissue is delicate and procedures can cause irreversible harm. Evaluate consent, likely clinical benefit, uncertainties and risks; a clear observed response does not justify every invasive investigation.<\/p>"}], "keypoints": ["Brain mapping uses observations of patients with damage, electrical stimulation and MRI.", "Complex connections make cause and effect difficult to isolate."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which technique images brain structure?", "opts": ["MRI", "A quadrat", "Benedict’s test"], "a": 0, "why": "MRI"}, {"q": "Why can damage studies be difficult to interpret?", "opts": ["Several connected functions can be affected", "All patients have identical damage", "The brain lacks connections"], "a": 0, "why": "Several connected functions can be affected"}], "exam": [{"q": "Evaluate electrical stimulation for mapping brain function.", "m": 3, "ms": ["It can link activity in a region to an observed response.", "Interconnected pathways limit conclusions about isolated functions.", "Risk of damage must be weighed against clinical benefit with informed consent."]}]}, {"id": "b-eye", "unit": "homeostasis", "title": "The eye and accommodation", "spec": "4.5.2.3", "paper": [2], "tier": "all", "separate": true, "summary": "Cornea and lens refract light onto the retina; the optic nerve carries impulses.", "notes": [{"title": "Understand the biology", "html": "<p>Cornea and lens refract light onto the retina; the optic nerve carries impulses. The sclera protects the eye. The iris changes pupil size: circular muscles contract and radial muscles relax in bright light, reducing entry; dim light reverses this.<\/p>"}, {"title": "Apply and explain", "html": "<p>For near focus, ciliary muscles contract, suspensory ligaments loosen and the lens becomes thicker. For distance, muscles relax, ligaments tighten and the lens thins. Myopia focuses before the retina and uses a concave correcting lens; hyperopia focuses behind and uses a convex lens. Treatments have benefits and risks.<\/p>"}], "keypoints": ["Cornea and lens refract light onto the retina; the optic nerve carries impulses.", "For near focus, ciliary muscles contract, suspensory ligaments loosen and the lens becomes thicker."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Near focus requires ciliary muscles to…", "opts": ["Become the pupil", "Contract", "Relax"], "a": 1, "why": "Contract"}, {"q": "Short sight is corrected using a…", "opts": ["Flat window only", "Concave lens", "Convex lens"], "a": 1, "why": "Concave lens"}], "exam": [{"q": "Describe how an eye focuses on a nearby object.", "m": 3, "ms": ["Ciliary muscles contract.", "Suspensory ligaments loosen.", "The lens thickens and refracts light more strongly onto the retina."]}]}, {"id": "b-temperature", "unit": "homeostasis", "title": "Body temperature control", "spec": "4.5.2.4", "paper": [2], "tier": "all", "separate": true, "summary": "The thermoregulatory centre in the brain monitors blood temperature and receives input from skin receptors.", "notes": [{"title": "Understand the biology", "html": "<p>The thermoregulatory centre in the brain monitors blood temperature and receives input from skin receptors. Too much warmth triggers sweating and dilation of vessels supplying skin. Cold triggers less sweating, constriction of skin vessels and shivering.<\/p>"}, {"title": "Apply and explain", "html": "<p>Begin an answer with the direction of the temperature change, then identify the response. Do not claim capillaries move nearer the skin. Distinguish the controlled internal temperature from changing outside temperature; these are automatic control responses, not conscious decisions.<\/p>"}], "keypoints": ["The thermoregulatory centre in the brain monitors blood temperature and receives input from skin receptors.", "Begin an answer with the direction of the temperature change, then identify the response."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which occurs when too warm?", "opts": ["Increased shivering", "Constriction of all skin vessels", "Increased sweating"], "a": 2, "why": "Increased sweating"}, {"q": "Where is the thermoregulatory centre?", "opts": ["Pancreas", "Bladder", "Brain"], "a": 2, "why": "Brain"}], "exam": [{"q": "Describe three responses to low core temperature.", "m": 3, "ms": ["Skin blood vessels constrict.", "Sweating decreases or stops.", "Skeletal muscles contract repeatedly, causing shivering."]}]}, {"id": "b-temperature-higher", "unit": "homeostasis", "title": "Explaining thermoregulation", "spec": "4.5.2.4 (HT)", "paper": [2], "tier": "higher", "separate": true, "summary": "Evaporation of sweat transfers energy from skin to the surroundings.", "notes": [{"title": "Understand the biology", "html": "<p>Evaporation of sweat transfers energy from skin to the surroundings. Vasodilation increases blood flow near the surface and energy transfer. In humid air, reduced evaporation can make sweating less effective, so visible sweat does not guarantee efficient cooling.<\/p>"}, {"title": "Apply and explain", "html": "<p>Vasoconstriction reduces surface blood flow and energy loss. Shivering involves muscle contraction and increased respiration, transferring energy to thermal stores. These responses oppose a fall in temperature and reduce when conditions recover: negative feedback.<\/p>"}], "keypoints": ["Evaporation of sweat transfers energy from skin to the surroundings.", "Vasoconstriction reduces surface blood flow and energy loss."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Why does sweat evaporation cool skin?", "opts": ["Energy is transferred away", "Glucose becomes oxygen", "Respiration stops"], "a": 0, "why": "Energy is transferred away"}, {"q": "Vasoconstriction conserves energy because…", "opts": ["Less warm blood flows near skin", "Capillaries leave the body", "The heart stops"], "a": 0, "why": "Less warm blood flows near skin"}], "exam": [{"q": "Explain how shivering and vasoconstriction help in cold conditions.", "m": 3, "ms": ["Shivering increases muscle contraction and respiration.", "More energy is transferred to thermal stores.", "Vasoconstriction reduces skin blood flow and transfer to surroundings."]}]}, {"id": "b-endocrine", "unit": "homeostasis", "title": "Endocrine glands, insulin and diabetes", "spec": "4.5.3.1–4.5.3.2", "paper": [2], "tier": "all", "separate": false, "summary": "Endocrine glands release hormones into blood; target tissues respond.", "notes": [{"title": "Understand the biology", "html": "<p>Endocrine glands release hormones into blood; target tissues respond. Effects are often slower and longer-lasting than nervous responses. Know pituitary, thyroid, adrenals, pancreas, ovaries and testes. Pituitary hormones influence several other glands.<\/p>"}, {"title": "Apply and explain", "html": "<p>High glucose stimulates pancreatic insulin, increasing glucose uptake and conversion to glycogen in liver and muscle. Type 1 diabetes involves too little insulin; type 2 involves poor cellular response to insulin. Insulin treatment, diet, exercise and other medicines have different roles depending on the condition.<\/p>"}], "keypoints": ["Endocrine glands release hormones into blood; target tissues respond.", "High glucose stimulates pancreatic insulin, increasing glucose uptake and conversion to glycogen in liver and muscle."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which gland secretes insulin?", "opts": ["Gall bladder", "Pancreas", "Thyroid"], "a": 1, "why": "Pancreas"}, {"q": "Glycogen is…", "opts": ["An enzyme", "A storage carbohydrate", "A hormone"], "a": 1, "why": "A storage carbohydrate"}], "exam": [{"q": "Explain how insulin lowers blood glucose after a meal.", "m": 3, "ms": ["The pancreas detects raised glucose and secretes insulin.", "Glucose moves from blood into cells.", "Excess glucose is converted to glycogen in liver and muscle."]}]}, {"id": "b-feedback", "unit": "homeostasis", "title": "Glucagon, adrenaline and thyroxine", "spec": "4.5.3.2, 4.5.3.7 (HT)", "paper": [2], "tier": "higher", "separate": false, "summary": "Low glucose stimulates pancreatic glucagon, causing liver glycogen to become glucose released into blood.", "notes": [{"title": "Understand the biology", "html": "<p>Low glucose stimulates pancreatic glucagon, causing liver glycogen to become glucose released into blood. Insulin and glucagon oppose departures from normal glucose levels. Corrective secretion decreases as conditions recover: negative feedback does not mean every response always lowers every variable.<\/p>"}, {"title": "Apply and explain", "html": "<p>Adrenaline from adrenals increases heart rate and oxygen/glucose delivery for fight or flight. Thyroxine from thyroid regulates basal metabolic rate and development. Low thyroxine stimulates pituitary signals promoting secretion; high thyroxine inhibits those signals.<\/p>"}], "keypoints": ["Low glucose stimulates pancreatic glucagon, causing liver glycogen to become glucose released into blood.", "Adrenaline from adrenals increases heart rate and oxygen/glucose delivery for fight or flight."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which raises low blood glucose?", "opts": ["Insulin", "Amylase", "Glucagon"], "a": 2, "why": "Glucagon"}, {"q": "Negative feedback…", "opts": ["Always lowers everything", "Requires conscious control", "Opposes the original change"], "a": 2, "why": "Opposes the original change"}], "exam": [{"q": "Explain correction of low blood glucose by negative feedback.", "m": 3, "ms": ["The pancreas detects the fall and releases glucagon.", "Liver glycogen is converted to glucose and released into blood.", "Glucagon secretion falls as glucose returns towards normal."]}]}, {"id": "b-kidneys", "unit": "homeostasis", "title": "Kidneys, excretion and treatment", "spec": "4.5.3.3", "paper": [2], "tier": "all", "separate": true, "summary": "Kidneys remove urea and regulate water and ions.", "notes": [{"title": "Understand the biology", "html": "<p>Excess amino acids are broken down and form urea in the liver; blood carries urea to kidneys for excretion. Kidneys regulate water and ions. Carbon dioxide leaves through lungs; water, ions and a little urea also leave in sweat. Cells losing or gaining too much water by osmosis do not work efficiently.<\/p>"}, {"title": "Apply and explain", "html": "<p>Dialysis removes waste through a partially permeable membrane using carefully balanced dialysis fluid. It requires regular treatment. A transplant can restore continuous function but requires a donor, surgery and management of rejection. Do not confuse producing urea in the liver with removing it in kidneys.<\/p>"}, {"title": "Filtration and reabsorption", "html": "<p>Kidneys filter blood and selectively reabsorb useful substances such as glucose, some ions and water. Urine normally contains urea, excess ions and water rather than blood cells. Compare values before and after filtration using the units and volumes given; the structure of the nephron is beyond this GCSE requirement.<\/p>"}], "keypoints": ["Urea is produced in the liver and removed from blood by the kidneys.", "Dialysis removes waste through a partially permeable membrane using carefully balanced dialysis fluid."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Where is urea produced?", "opts": ["Liver", "Bladder", "Lungs"], "a": 0, "why": "Liver"}, {"q": "Which treatment uses exchange across a membrane?", "opts": ["Dialysis", "A stent", "A pacemaker"], "a": 0, "why": "Dialysis"}], "exam": [{"q": "Compare dialysis and a kidney transplant.", "m": 3, "ms": ["Dialysis removes wastes but requires regular time-consuming treatment.", "A successful transplant provides more continuous kidney function.", "Transplantation requires a donor and involves surgical / rejection risks."]}]}, {"id": "b-kidney-filtration", "unit": "homeostasis", "title": "Selective reabsorption and ADH", "spec": "4.5.3.3 (HT)", "paper": [2], "tier": "higher", "separate": true, "summary": "Kidneys filter blood and selectively reabsorb all glucose, appropriate ions and sufficient water.", "notes": [{"title": "Understand the biology", "html": "<p>Kidneys filter blood and selectively reabsorb all glucose, appropriate ions and sufficient water. Amino-acid deamination removes the nitrogen-containing part in the liver; ammonia is converted to urea for safer excretion. These details explain why urine composition differs from blood.<\/p>"}, {"title": "Apply and explain", "html": "<p>Low blood water level is detected in the brain; pituitary ADH increases kidney-tubule permeability, so more water returns to blood. Urine becomes smaller in volume and more concentrated. Plenty of water reduces ADH and increases dilute urine. ADH changes reabsorption, not water creation.<\/p>"}], "keypoints": ["Kidneys filter blood and selectively reabsorb all glucose, appropriate ions and sufficient water.", "Low blood water level is detected in the brain; pituitary ADH increases kidney-tubule permeability, so more water returns to blood."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "More ADH normally produces…", "opts": ["No change", "Less, more concentrated urine", "More concentrated urine in a larger volume"], "a": 1, "why": "Less, more concentrated urine"}, {"q": "Which useful molecule is normally fully reabsorbed?", "opts": ["Carbon dioxide", "Glucose", "Urea"], "a": 1, "why": "Glucose"}], "exam": [{"q": "Explain the ADH response to water loss during exercise.", "m": 3, "ms": ["The brain detects low blood water concentration and the pituitary releases more ADH.", "Kidney tubules become more permeable and reabsorb more water.", "A smaller volume of more concentrated urine is produced."]}]}, {"id": "b-reproductive-hormones", "unit": "homeostasis", "title": "Reproductive hormones and contraception", "spec": "4.5.3.4–4.5.3.5", "paper": [2], "tier": "all", "separate": false, "summary": "Testosterone from testes supports sperm production and male secondary sexual characteristics; ovarian oestrogen supports female development.", "notes": [{"title": "Understand the biology", "html": "<p>Testosterone from testes supports sperm production and male secondary sexual characteristics; ovarian oestrogen supports female development. FSH matures an egg and LH triggers ovulation. Oestrogen and progesterone maintain the uterus lining. Twenty-eight days is a cycle model; real cycle lengths vary.<\/p>"}, {"title": "Apply and explain", "html": "<p>Hormonal methods can inhibit egg maturation or release. Barriers prevent sperm reaching eggs; condoms also reduce some STI transmission. Intrauterine devices, spermicides, fertility-awareness methods and sterilisation differ in effectiveness, risks and reversibility. Compare typical-use data where given.<\/p>"}], "keypoints": ["Testosterone from testes supports sperm production and male secondary sexual characteristics; ovarian oestrogen supports female development.", "Hormonal methods can inhibit egg maturation or release."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which triggers ovulation?", "opts": ["Insulin", "Thyroxine", "LH"], "a": 2, "why": "LH"}, {"q": "Which can also reduce STI transmission?", "opts": ["Hormone implant alone", "Sterilisation alone", "Condom"], "a": 2, "why": "Condom"}], "exam": [{"q": "Compare a condom and a hormonal implant.", "m": 3, "ms": ["Condoms form a barrier preventing sperm reaching eggs.", "Implants release hormones to inhibit egg maturation or release without action at every intercourse.", "Condoms reduce some STI transmission; implants alone do not."]}]}, {"id": "b-cycle-ivf", "unit": "homeostasis", "title": "Hormone interactions and IVF", "spec": "4.5.3.4, 4.5.3.6 (HT)", "paper": [2], "tier": "higher", "separate": false, "summary": "FSH stimulates egg maturation and oestrogen secretion.", "notes": [{"title": "Understand the biology", "html": "<p>FSH stimulates egg maturation and oestrogen secretion. Oestrogen rebuilds the lining, inhibits FSH and stimulates an LH surge. LH causes ovulation; progesterone maintains the lining and inhibits FSH/LH. Falling progesterone allows the lining to break down if pregnancy does not occur.<\/p>"}, {"title": "Apply and explain", "html": "<p>Fertility drugs use FSH/LH. IVF matures several eggs, collects them, fertilises them in a laboratory and transfers one or two early embryos to the uterus. Success is uncertain; consider physical and emotional demands, cost and multiple-pregnancy risks as well as benefits.<\/p>"}], "keypoints": ["FSH stimulates egg maturation and oestrogen secretion.", "Fertility drugs use FSH/LH."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "What stimulates the LH surge in the model?", "opts": ["Increased oestrogen", "Increased insulin", "Permanent absence of FSH"], "a": 0, "why": "Increased oestrogen"}, {"q": "Where does fertilisation happen in IVF?", "opts": ["Laboratory", "Bladder", "Pituitary"], "a": 0, "why": "Laboratory"}], "exam": [{"q": "Explain hormone use in IVF and give one limitation.", "m": 3, "ms": ["FSH/LH stimulate maturation of several eggs / ovulation.", "Eggs are collected and fertilised in a laboratory before embryo transfer.", "A valid limitation includes variable success, treatment stress or multiple births."]}]}, {"id": "b-tropisms", "unit": "homeostasis", "title": "Plant growth responses", "spec": "4.5.4.1", "paper": [2], "tier": "all", "separate": true, "summary": "Shoots grow towards light and against gravity; roots usually grow with gravity.", "notes": [{"title": "Understand the biology", "html": "<p>Shoots grow towards light and against gravity; roots usually grow with gravity. These are directional growth responses, not movement of the whole plant. Auxin is associated with unequal growth. Label phototropism and gravitropism using the stimulus and response direction.<\/p>"}, {"title": "Apply and explain", "html": "<p>Test similar seedlings with one-sided light and a suitable control, or change orientation while controlling illumination. Keep age, species, water and temperature constant. Repeat and record lengths and labelled drawings. Change light or gravity separately to isolate the factor.<\/p>"}, {"title": "Unequal growth", "html": "<p>Plant hormones coordinate growth. Unequal auxin distribution causes different growth rates on opposite sides of a root or shoot, producing bending. This is growth through differential elongation rather than a muscle contraction.<\/p>"}], "keypoints": ["Shoots grow towards light and against gravity; roots usually grow with gravity.", "Test similar seedlings with one-sided light and a suitable control, or change orientation while controlling illumination."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Growth towards light is…", "opts": ["A conscious reflex", "Positive phototropism", "Negative osmosis"], "a": 1, "why": "Positive phototropism"}, {"q": "Most roots show…", "opts": ["Positive phototropism only", "Positive gravitropism", "No response to gravity"], "a": 1, "why": "Positive gravitropism"}], "exam": [{"q": "Plan an investigation into shoot response to one-sided light.", "m": 3, "ms": ["Use similar seedlings with one-sided light and an appropriately lit control.", "Control water, temperature, species and age.", "Repeat and record growth direction with measurements and labelled drawings."]}], "practical": {"title": "Required practical 8 · Seedling growth responses", "method": ["Use similar newly germinated seedlings.", "Investigate one-sided light with an appropriate control, or alter orientation while controlling illumination for gravity.", "Measure growth and make labelled drawings over time with several seedlings."], "variables": ["Independent: light direction or orientation, tested separately.", "Dependent: growth direction and length change.", "Control species, age, water and temperature."], "safety": ["Wash hands after handling growing media.", "Keep electrical lighting safely away from water."], "analysis": "Compare initial and final measurements with controls. Repetition separates a consistent directional response from natural variation."}}, {"id": "b-plant-hormones", "unit": "homeostasis", "title": "Explaining and using plant hormones", "spec": "4.5.4.1–4.5.4.2 (HT)", "paper": [2], "tier": "higher", "separate": true, "summary": "In a shoot lit from one side, auxin accumulates on the shaded side and promotes elongation, causing bending towards light.", "notes": [{"title": "Understand the biology", "html": "<p>In a shoot lit from one side, auxin accumulates on the shaded side and promotes elongation, causing bending towards light. Auxin inhibits elongation in roots at concentrations that promote shoot growth, helping explain opposite responses to gravity.<\/p>"}, {"title": "Apply and explain", "html": "<p>Auxins are used in rooting powders, tissue culture and selective weedkillers. Gibberellins promote germination, flowering and fruit growth. Ethene controls ripening, allowing timing after transport. Link hormone action to benefit and consider dose, cost and non-target effects.<\/p>"}], "keypoints": ["In a shoot lit from one side, auxin accumulates on the shaded side and promotes elongation, causing bending towards light.", "Auxins are used in rooting powders, tissue culture and selective weedkillers."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which controls ripening?", "opts": ["ADH", "Insulin", "Ethene"], "a": 2, "why": "Ethene"}, {"q": "A shoot bends towards light because…", "opts": ["The lit side always elongates faster", "It contracts like muscle", "The shaded side elongates faster"], "a": 2, "why": "The shaded side elongates faster"}], "exam": [{"q": "Explain the benefit of auxin rooting powder for commercial cuttings.", "m": 3, "ms": ["Auxin promotes root formation.", "Roots allow cuttings to establish as new plants.", "Many plants retaining the parent genotype can be produced."]}]}, {"id": "b-repro", "unit": "inheritance", "title": "Reproduction, meiosis and fertilisation", "spec": "4.6.1.1–4.6.1.2", "paper": [2], "tier": "all", "separate": false, "summary": "Sexual reproduction joins gametes and mixes genetic information.", "notes": [{"title": "Understand the biology", "html": "<p>Sexual reproduction joins gametes and mixes genetic information. DNA is replicated once before meiosis, followed by two cell divisions, making four genetically different cells with half the original chromosome number. Human gametes normally have 23 chromosomes; chromosome number is not the same as cell number.<\/p>"}, {"title": "Apply and explain", "html": "<p>Fertilisation restores paired chromosomes. The zygote grows by mitosis and its cells differentiate. Asexual reproduction has one parent, no gamete fusion and genetically identical offspring apart from mutation. Meiosis creates gametes; mitosis supports growth and asexual reproduction.<\/p>"}], "keypoints": ["Sexual reproduction joins gametes and mixes genetic information.", "Fertilisation restores paired chromosomes."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Body cells have 30 chromosomes. How many in a normal gamete?", "a": 15, "unit": "", "tol": 0.005, "why": "Meiosis halves 30 to 15."}, {"q": "What restores the full chromosome number?", "opts": ["Fertilisation", "Meiosis alone", "Diffusion"], "a": 0, "why": "Fertilisation"}], "exam": [{"q": "Explain maintenance of chromosome number across generations.", "m": 3, "ms": ["Meiosis halves the chromosome number in gametes.", "Two gametes fuse at fertilisation.", "Their sets combine to restore the normal paired chromosome number."]}]}, {"id": "b-repro-evaluation", "unit": "inheritance", "title": "Evaluating reproductive strategies", "spec": "4.6.1.3", "paper": [2], "tier": "all", "separate": true, "summary": "Asexual reproduction is fast, needs no mate and preserves a successful genotype in favourable conditions.", "notes": [{"title": "Understand the biology", "html": "<p>Asexual reproduction is fast, needs no mate and preserves a successful genotype in favourable conditions. Sexual reproduction requires more time and energy but generates variation, improving the chance that some offspring survive a changed environment or new disease.<\/p>"}, {"title": "Apply and explain", "html": "<p>Strawberries can form runners as well as seeds; daffodils divide bulbs. Many fungi use both strategies. Malaria protists reproduce asexually in humans and sexually in mosquitoes. Use the stated conditions to decide which strategy has an advantage.<\/p>"}], "keypoints": ["Asexual reproduction is fast, needs no mate and preserves a successful genotype in favourable conditions.", "Strawberries can form runners as well as seeds; daffodils divide bulbs."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "An advantage of asexual reproduction is…", "opts": ["Gametes must fuse", "No mate is needed", "Maximum variation is guaranteed"], "a": 1, "why": "No mate is needed"}, {"q": "Which is asexual?", "opts": ["Fertilisation in a flower", "A strawberry runner forming a plant", "Fusion of sperm and egg"], "a": 1, "why": "A strawberry runner forming a plant"}], "exam": [{"q": "Why may sexual reproduction help when a new disease appears?", "m": 3, "ms": ["It generates genetic variation.", "Some offspring may inherit resistance.", "Resistant individuals are more likely to survive and reproduce."]}]}, {"id": "b-dna", "unit": "inheritance", "title": "DNA, genes and the genome", "spec": "4.6.1.4", "paper": [2], "tier": "all", "separate": false, "summary": "DNA is a polymer with two strands forming a double helix.", "notes": [{"title": "Understand the biology", "html": "<p>DNA is a polymer with two strands forming a double helix. Chromosomes contain DNA; genes are sections coding for amino acid sequences in proteins. A genome is the entire genetic material of an organism. Alleles are versions of genes, not additional organelles.<\/p>"}, {"title": "Apply and explain", "html": "<p>Genome knowledge can identify disease-associated genes, support research and trace human migration. A variant may increase risk without determining outcome because other genes and environment matter. Evaluate privacy and consent when genetic data are shared.<\/p>"}], "keypoints": ["DNA is a polymer with two strands forming a double helix.", "Genome knowledge can identify disease-associated genes, support research and trace human migration."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "A genome is…", "opts": ["One protein", "One chromosome only", "All genetic material of an organism"], "a": 2, "why": "All genetic material of an organism"}, {"q": "A gene codes for…", "opts": ["A mineral ion", "A whole organ directly", "An amino acid sequence in a protein"], "a": 2, "why": "An amino acid sequence in a protein"}], "exam": [{"q": "Give a medical use and limitation of genome knowledge.", "m": 3, "ms": ["It can identify variants associated with an inherited disorder.", "This can support diagnosis, risk assessment or treatment research.", "Variants may not determine outcome because other genes and environment contribute."]}]}, {"id": "b-nucleotides", "unit": "inheritance", "title": "DNA nucleotides and triplets", "spec": "4.6.1.5", "paper": [2], "tier": "all", "separate": true, "summary": "A DNA nucleotide contains sugar, phosphate and one base: A, C, G or T.", "notes": [{"title": "Understand the biology", "html": "<p>A DNA nucleotide contains sugar, phosphate and one base: A, C, G or T. Repeated sugar and phosphate groups form the backbone. Groups of three bases code for amino acids, so base order determines the order of amino acids.<\/p>"}, {"title": "Apply and explain", "html": "<p>Proteins are amino acid chains, not DNA-base chains. A simplified coding sequence of twelve bases has four triplets. This calculation is a model rather than a claim that real genes contain only uninterrupted coding DNA.<\/p>"}], "keypoints": ["A DNA nucleotide contains sugar, phosphate and one base: A, C, G or T.", "Proteins are amino acid chains, not DNA-base chains."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "A simplified sequence has 36 coding bases. How many triplets?", "a": 12, "unit": "", "tol": 0.005, "why": "36/3 = 12."}, {"q": "Every DNA nucleotide contains…", "opts": ["Sugar, phosphate and a base", "A whole chromosome", "Three amino acids"], "a": 0, "why": "Sugar, phosphate and a base"}], "exam": [{"q": "Describe how DNA stores information for a protein.", "m": 3, "ms": ["DNA uses four possible bases.", "Their sequence carries the information.", "Base triplets specify the amino acid sequence."]}]}, {"id": "b-protein", "unit": "inheritance", "title": "Protein synthesis and genetic variants", "spec": "4.6.1.5 (HT)", "paper": [2], "tier": "higher", "separate": true, "summary": "Complementary bases pair A–T and C–G.", "notes": [{"title": "Understand the biology", "html": "<p>Complementary bases pair A–T and C–G. A template carries gene instructions to ribosomes; carrier molecules bring amino acids in sequence. The completed chain folds into a functional shape. Detailed RNA structures are beyond the GCSE requirement.<\/p>"}, {"title": "Apply and explain", "html": "<p>Many mutations have little effect, but some alter amino acids, folding and protein function. Non-coding variants can change gene expression instead of protein sequence. Explain the intermediate protein effect before predicting a phenotype; not every mutation is harmful.<\/p>"}], "keypoints": ["Complementary bases pair A–T and C–G.", "Many mutations have little effect, but some alter amino acids, folding and protein function."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "C pairs with…", "opts": ["T", "G", "A"], "a": 1, "why": "G"}, {"q": "A non-coding variant may…", "opts": ["Turn DNA into lipid", "Change gene expression", "Always kill a cell"], "a": 1, "why": "Change gene expression"}], "exam": [{"q": "Explain how a mutation could reduce enzyme activity.", "m": 3, "ms": ["A DNA change may alter amino acid sequence.", "Protein folding / active-site shape can change.", "The substrate may fit less well, reducing catalysis."]}]}, {"id": "b-inheritance", "unit": "inheritance", "title": "Alleles, disorders and sex inheritance", "spec": "4.6.1.6–4.6.1.8", "paper": [2], "tier": "all", "separate": false, "summary": "Genotype describes alleles and phenotype describes expressed characteristics.", "notes": [{"title": "Understand the biology", "html": "<p>Genotype describes alleles and phenotype describes expressed characteristics. Homozygous means identical alleles; heterozygous means different alleles. A dominant allele is expressed in a heterozygote. Dominant does not mean more common, stronger or beneficial.<\/p>"}, {"title": "Apply and explain", "html": "<p>Cystic fibrosis uses a recessive inheritance model; polydactyly can be dominant. Interpret pedigrees using the stated symbols and model. In the standard sex-chromosome model, XX is female and XY male; sperm can supply X or Y, giving approximately equal probabilities.<\/p>"}, {"title": "Evaluate embryo screening", "html": "<p>Genetic screening can identify embryos carrying a disorder allele before implantation. Potential benefits include reducing the chance of a serious inherited condition, while limitations include cost, uncertain predictions and ethical concerns about selecting embryos. Evaluate the condition and evidence given without assuming screening guarantees a healthy child.<\/p>"}], "keypoints": ["Genotype describes alleles and phenotype describes expressed characteristics.", "Cystic fibrosis uses a recessive inheritance model; polydactyly can be dominant."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Heterozygous means…", "opts": ["Two identical alleles", "No chromosomes", "Two different alleles"], "a": 2, "why": "Two different alleles"}, {"q": "Why can a recessive carrier be unaffected?", "opts": ["The recessive allele disappears", "The person has no DNA", "A dominant allele masks the recessive effect"], "a": 2, "why": "A dominant allele masks the recessive effect"}], "exam": [{"q": "Two unaffected parents have a child with a recessive disorder. Explain their genotypes in the single-gene model.", "m": 3, "ms": ["Each must carry the recessive allele inherited by the affected child.", "Each also has a dominant allele because they are unaffected.", "Both are heterozygous carriers."]}]}, {"id": "b-crosses", "unit": "inheritance", "title": "Constructing Punnett squares", "spec": "4.6.1.6 (HT)", "paper": [2], "tier": "higher", "separate": false, "summary": "An Aa parent forms gametes carrying A or a, not both.", "notes": [{"title": "Understand the biology", "html": "<p>An Aa parent forms gametes carrying A or a, not both. Combine one gamete from each parent in a grid. Aa × Aa gives AA, Aa, Aa and aa, each cell equally likely in the simple model.<\/p>"}, {"title": "Apply and explain", "html": "<p>Probability is not a fixed family outcome. A 25% risk does not guarantee one affected child in every four. Independent births retain the same probability regardless of previous births; expected number equals probability multiplied by sample size.<\/p>"}], "keypoints": ["An Aa parent forms gametes carrying A or a, not both.", "Probability is not a fixed family outcome."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Aa × Aa: expected percentage aa?", "a": 25, "unit": "%", "tol": 0.005, "why": "One of four combinations is aa."}, {"q": "Risk is 0.25 among 80 offspring. Expected affected number?", "a": 20, "unit": "", "tol": 0.005, "why": "0.25 × 80 = 20."}], "exam": [{"q": "Construct outcomes for Aa × aa and state the recessive phenotype percentage.", "m": 3, "ms": ["Gametes are A/a and a.", "Offspring are Aa and aa in equal proportions.", "The expected recessive phenotype percentage is 50%."]}], "sim": "genetics"}, {"id": "b-selection", "unit": "inheritance", "title": "Variation, natural selection and selective breeding", "spec": "4.6.2.1–4.6.2.3", "paper": [2], "tier": "all", "separate": false, "summary": "Variation can be genetic, environmental or both.", "notes": [{"title": "Understand the biology", "html": "<p>Variation can be genetic, environmental or both. Mutations create new variants and sexual reproduction reshuffles information. Inherited variants improving survival and reproduction can become more frequent over generations through natural selection. Individuals do not deliberately evolve because they need to.<\/p>"}, {"title": "Apply and explain", "html": "<p>Selective breeding chooses parents with desired traits, breeds them, selects suitable offspring and repeats. It can improve yield but reduce genetic diversity and increase inherited defects through inbreeding. Distinguish human choice of parents from environmental selection.<\/p>"}], "keypoints": ["Variation can be genetic, environmental or both.", "Selective breeding chooses parents with desired traits, breeds them, selects suitable offspring and repeats."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "New genetic variants originate through…", "opts": ["A need automatically changing genes", "Mutation", "An organism deciding to change"], "a": 1, "why": "Mutation"}, {"q": "A risk of inbreeding is…", "opts": ["No shared alleles", "More inherited defects and reduced diversity", "Guaranteed immunity"], "a": 1, "why": "More inherited defects and reduced diversity"}], "exam": [{"q": "Explain how drought resistance becomes more common in a wild plant population.", "m": 3, "ms": ["Plants vary genetically in drought resistance.", "More resistant plants survive and reproduce more successfully.", "Resistance alleles pass to offspring and increase in frequency."]}]}, {"id": "b-engineering", "unit": "inheritance", "title": "Genetic engineering: benefits and risks", "spec": "4.6.2.4", "paper": [2], "tier": "all", "separate": false, "summary": "Genetic engineering introduces a gene to produce a desired characteristic.", "notes": [{"title": "Understand the biology", "html": "<p>Genetic engineering introduces a gene to produce a desired characteristic. Modified bacteria can produce human insulin; crops can resist pests or herbicides. This differs from selective breeding, which selects parents carrying existing traits.<\/p>"}, {"title": "Apply and explain", "html": "<p>Pest resistance may reduce crop loss and some insecticide use. Evaluate non-target effects, gene movement to wild relatives and economic implications. Distinguish a possible concern from demonstrated harm and assess the specific modification using comparative evidence.<\/p>"}], "keypoints": ["Genetic engineering introduces a gene to produce a desired characteristic.", "Pest resistance may reduce crop loss and some insecticide use."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which is genetic engineering?", "opts": ["Choosing high-yield parents only", "Water entering roots", "Giving bacteria a human insulin gene"], "a": 2, "why": "Giving bacteria a human insulin gene"}, {"q": "Why can pest resistance raise yield?", "opts": ["Plants never need water", "Respiration stops", "Less tissue is lost to pests"], "a": 2, "why": "Less tissue is lost to pests"}], "exam": [{"q": "Evaluate planting a pest-resistant crop near a wildflower habitat.", "m": 3, "ms": ["Reduced pest loss or insecticide use may improve yield.", "Possible non-target effects or gene transfer should be investigated.", "A judgement should use evidence specific to the crop and habitat."]}]}, {"id": "b-engineering-steps", "unit": "inheritance", "title": "Transferring genes using vectors", "spec": "4.6.2.4 (HT)", "paper": [2], "tier": "higher", "separate": false, "summary": "Enzymes isolate a desired gene, which is inserted into a vector such as a plasmid or virus.", "notes": [{"title": "Understand the biology", "html": "<p>Enzymes isolate a desired gene, which is inserted into a vector such as a plasmid or virus. The vector transfers it into recipient cells. Modifying plant or animal cells early in development allows the organism to develop with the characteristic.<\/p>"}, {"title": "Apply and explain", "html": "<p>The gene encodes the desired protein while the vector carries it. Not all recipient cells necessarily acquire or express the gene; successful modified cells are selected and grown. Distinguish donor organism, isolated gene, vector and recipient in an explanation.<\/p>"}], "keypoints": ["Enzymes isolate a desired gene, which is inserted into a vector such as a plasmid or virus.", "The gene encodes the desired protein while the vector carries it."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "A vector…", "opts": ["Carries a gene into a recipient cell", "Provides all energy", "Destroys every gene"], "a": 0, "why": "Carries a gene into a recipient cell"}, {"q": "Genes are isolated using…", "opts": ["Enzymes", "Quadrats", "Only a ruler"], "a": 0, "why": "Enzymes"}], "exam": [{"q": "Describe genetic engineering to produce a human protein in bacteria.", "m": 3, "ms": ["Use enzymes to isolate the human gene.", "Insert it into a vector such as a plasmid.", "Transfer it into bacterial cells and grow suitable modified cells."]}]}, {"id": "b-cloning", "unit": "inheritance", "title": "Cloning plants and animals", "spec": "4.6.2.5", "paper": [2], "tier": "all", "separate": true, "summary": "Cuttings and sterile tissue culture reproduce useful plant genotypes.", "notes": [{"title": "Understand the biology", "html": "<p>Cuttings and sterile tissue culture reproduce useful plant genotypes. They can rapidly produce many plants, but low diversity creates shared vulnerability. Embryo transplants split early unspecialised embryo cells before implantation into host mothers.<\/p>"}, {"title": "Apply and explain", "html": "<p>Adult-cell cloning replaces an egg nucleus with an adult body-cell nucleus, stimulates development and implants the embryo. Nuclear DNA matches the body-cell donor. Consider low success, animal welfare and conservation potential rather than describing cloning as risk-free.<\/p>"}], "keypoints": ["Cuttings and sterile tissue culture reproduce useful plant genotypes.", "Adult-cell cloning replaces an egg nucleus with an adult body-cell nucleus, stimulates development and implants the embryo."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which uses small plant cell groups in sterile medium?", "opts": ["Meiosis", "Tissue culture", "Pollination"], "a": 1, "why": "Tissue culture"}, {"q": "A clone’s nuclear DNA matches…", "opts": ["All donors equally", "The body-cell nucleus donor", "The host automatically"], "a": 1, "why": "The body-cell nucleus donor"}], "exam": [{"q": "Explain one benefit and two risks of growing cloned crops.", "m": 3, "ms": ["They retain a desired parental genotype / trait.", "Low genetic diversity can leave the crop vulnerable to the same pathogen.", "The same environmental change may affect many genetically similar plants."]}]}, {"id": "b-history", "unit": "inheritance", "title": "Darwin, Wallace, Mendel and speciation", "spec": "4.6.3.1–4.6.3.3", "paper": [2], "tier": "all", "separate": true, "summary": "Darwin and Wallace independently developed natural selection.", "notes": [{"title": "Understand the biology", "html": "<p>Darwin and Wallace independently developed natural selection. Acceptance was slowed by limited evidence, religious beliefs and poor understanding of inheritance. Lamarck proposed inherited acquired characteristics, which does not generally explain genetic evolution. Mendel found inheritance patterns through pea crosses before DNA was understood.<\/p>"}, {"title": "Apply and explain", "html": "<p>Isolation prevents gene flow between populations. Different conditions favour different alleles and mutations add variation. Over generations, populations may diverge until they cannot interbreed to produce fertile offspring. New genetic evidence can revise scientific explanations.<\/p>"}], "keypoints": ["Darwin and Wallace independently developed natural selection.", "Isolation prevents gene flow between populations."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "What limited early acceptance of Darwin’s explanation?", "opts": ["No variation existed", "All fossils were living", "Inheritance mechanisms were unknown"], "a": 2, "why": "Inheritance mechanisms were unknown"}, {"q": "Species are separated in the usual reproductive model when…", "opts": ["They live one kilometre apart", "They differ slightly in height", "They cannot interbreed to produce fertile offspring"], "a": 2, "why": "They cannot interbreed to produce fertile offspring"}], "exam": [{"q": "Explain speciation following geographical isolation.", "m": 3, "ms": ["A barrier separates populations and prevents gene flow.", "Different selection pressures favour different alleles.", "Accumulated differences prevent interbreeding to produce fertile offspring."]}]}, {"id": "b-evidence", "unit": "inheritance", "title": "Fossils, extinction and resistance", "spec": "4.6.3 (shared content)", "paper": [2], "tier": "all", "separate": false, "summary": "Fossils form from preserved remains, mineral replacement or traces such as footprints.", "notes": [{"title": "Understand the biology", "html": "<p>Fossils form from preserved remains, mineral replacement or traces such as footprints. The record is incomplete because soft organisms decay, fossilisation is unusual and rocks can be destroyed. Extinction can follow habitat change, new predators, disease or catastrophic events.<\/p>"}, {"title": "Apply and explain", "html": "<p>Random variants can give antibiotic resistance. Antibiotics kill susceptible bacteria, leaving resistant survivors to reproduce. Treatment selects existing variants rather than making bacteria choose to adapt. Appropriate prescribing and infection prevention help reduce selection and transmission.<\/p>"}], "keypoints": ["Fossils form from preserved remains, mineral replacement or traces such as footprints.", "Random variants can give antibiotic resistance."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Why is the fossil record incomplete?", "opts": ["Many organisms decayed without fossilising", "Every organism fossilises", "Rocks only preserve living cells"], "a": 0, "why": "Many organisms decayed without fossilising"}, {"q": "A resistant survivor may…", "opts": ["Reproduce and pass resistance on", "Lose all DNA", "Become a virus"], "a": 0, "why": "Reproduce and pass resistance on"}], "exam": [{"q": "Explain rising resistance during repeated antibiotic exposure.", "m": 3, "ms": ["Random variation / mutation gives some bacteria resistance.", "Susceptible bacteria are killed while resistant bacteria survive.", "Survivors reproduce and pass on resistance."]}]}, {"id": "b-classification", "unit": "inheritance", "title": "Classification and evolutionary trees", "spec": "4.6.4", "paper": [2], "tier": "all", "separate": false, "summary": "The hierarchy is kingdom, phylum, class, order, family, genus and species.", "notes": [{"title": "Understand the biology", "html": "<p>The hierarchy is kingdom, phylum, class, order, family, genus and species. Binomial names combine genus and species. Trees represent proposed common ancestry; organisms sharing a more recent common ancestor are more closely related.<\/p>"}, {"title": "Apply and explain", "html": "<p>Molecular and improved microscopic evidence led to Bacteria, Archaea and Eukaryota as domains. Similar appearance need not imply close relationship. Read a tree through its branching points rather than the physical distance between printed names.<\/p>"}], "keypoints": ["The hierarchy is kingdom, phylum, class, order, family, genus and species.", "Molecular and improved microscopic evidence led to Bacteria, Archaea and Eukaryota as domains."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which is broadest?", "opts": ["Species", "Kingdom", "Genus"], "a": 1, "why": "Kingdom"}, {"q": "Which shows closest relationship?", "opts": ["The longest names", "The most recent common ancestor", "Names printed side by side"], "a": 1, "why": "The most recent common ancestor"}], "exam": [{"q": "Explain why DNA evidence can change classification.", "m": 3, "ms": ["It reveals genetic similarities and differences.", "These indicate evolutionary relationships not obvious from appearance.", "Classification can be revised to reflect common ancestry."]}]}, {"id": "b-community", "unit": "ecology", "title": "Communities and environmental factors", "spec": "4.7.1.1–4.7.1.3", "paper": [2], "tier": "all", "separate": false, "summary": "A population is one species in an area; a community includes all populations; an ecosystem includes the non-living environment.", "notes": [{"title": "Understand the biology", "html": "<p>A population is one species in an area; a community includes all populations; an ecosystem includes the non-living environment. Plants compete for light, water, minerals and space; animals for food, mates and territory. Interdependence links species through feeding, pollination and shelter.<\/p>"}, {"title": "Apply and explain", "html": "<p>Biotic factors include predators, pathogens and competitors. Abiotic factors include temperature, light, oxygen, water and pH. Changing one factor may affect many populations. Stability means relatively balanced populations, not numbers that never vary.<\/p>"}], "keypoints": ["A population is one species in an area; a community includes all populations; an ecosystem includes the non-living environment.", "Biotic factors include predators, pathogens and competitors."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which is abiotic?", "opts": ["Predator abundance", "A pathogen", "Soil pH"], "a": 2, "why": "Soil pH"}, {"q": "Which is a population?", "opts": ["Every meadow species", "Soil plus all organisms", "All rabbits in a meadow"], "a": 2, "why": "All rabbits in a meadow"}], "exam": [{"q": "Explain possible effects of introducing a predator to a meadow.", "m": 3, "ms": ["It can reduce prey abundance.", "Changes in prey affect their food organisms or competitors.", "Interdependence can cause further community changes."]}]}, {"id": "b-adaptation", "unit": "ecology", "title": "Adaptations and extremophiles", "spec": "4.7.1.4", "paper": [2], "tier": "all", "separate": false, "summary": "Adaptations can be structural, behavioural or functional.", "notes": [{"title": "Understand the biology", "html": "<p>Adaptations can be structural, behavioural or functional. Link a feature to its environmental challenge and survival benefit. Thick insulation conserves thermal energy; nocturnal activity can avoid daytime heat. Individuals do not acquire inherited adaptations simply because they need them.<\/p>"}, {"title": "Apply and explain", "html": "<p>Extremophiles inhabit conditions such as high heat, pressure or salinity. Desert plants may have waxy cuticles, reduced leaves and water stores. Trade-offs matter: reducing leaf area conserves water but can reduce light capture. Different adaptations may solve the same problem.<\/p>"}], "keypoints": ["Adaptations can be structural, behavioural or functional.", "Extremophiles inhabit conditions such as high heat, pressure or salinity."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which is behavioural?", "opts": ["Nocturnal activity", "A waxy cuticle", "A long root"], "a": 0, "why": "Nocturnal activity"}, {"q": "Why may desert leaves be small?", "opts": ["To reduce water loss area", "To stop respiration", "To absorb sunlight as water"], "a": 0, "why": "To reduce water loss area"}], "exam": [{"q": "Explain how a thick cuticle and extensive roots benefit a desert plant.", "m": 3, "ms": ["Cuticle reduces evaporation from leaves.", "Extensive roots access a larger soil volume or deeper water.", "Together they help maintain water supply in dry conditions."]}]}, {"id": "b-foodchains", "unit": "ecology", "title": "Food chains and predator–prey cycles", "spec": "4.7.2.1", "paper": [2], "tier": "all", "separate": false, "summary": "Producers make biomass, usually by photosynthesis.", "notes": [{"title": "Understand the biology", "html": "<p>Producers make biomass, usually by photosynthesis. Primary consumers eat producers and secondary consumers eat primary consumers. Arrows show biomass movement from food to feeder. Food webs represent several linked feeding relationships.<\/p>"}, {"title": "Apply and explain", "html": "<p>More prey can support predator reproduction; more predators can reduce prey, after which predators may decline through food shortage. Changes lag rather than occurring instantly. Weather, disease and competition also influence real populations, so simple cycles are models.<\/p>"}], "keypoints": ["Producers make biomass, usually by photosynthesis.", "More prey can support predator reproduction; more predators can reduce prey, after which predators may decline through food shortage."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Grass → rabbit → fox: the rabbit is…", "opts": ["A tertiary consumer", "A primary consumer", "A producer"], "a": 1, "why": "A primary consumer"}, {"q": "Why can predator peaks follow prey peaks?", "opts": ["Axes always run backwards", "Extra prey first supports predator survival and reproduction", "Predators photosynthesise"], "a": 1, "why": "Extra prey first supports predator survival and reproduction"}], "exam": [{"q": "Explain why predator numbers may decline after prey numbers fall.", "m": 3, "ms": ["Less prey means less food.", "Predator survival / reproduction falls.", "Population changes occur after a time delay."]}], "sim": "population"}, {"id": "b-sampling", "unit": "ecology", "title": "Quadrats, transects and abundance", "spec": "4.7.2.1", "paper": [2], "tier": "all", "separate": false, "summary": "Use random coordinates to avoid choosing favourable quadrat locations.", "notes": [{"title": "Understand the biology", "html": "<p>Use random coordinates to avoid choosing favourable quadrat locations. Count consistently and repeat widely. Mean count divided by quadrat area gives density; density times habitat area estimates population. Uneven distribution makes this an estimate, not an exact census.<\/p>"}, {"title": "Apply and explain", "html": "<p>A transect investigates distribution along a gradient. Use quadrats at measured intervals and measure the relevant abiotic factor. Repeat transects and standardise counting rules. A correlation with light does not rule out variation in moisture or soil.<\/p>"}], "keypoints": ["Use random coordinates to avoid choosing favourable quadrat locations.", "A transect investigates distribution along a gradient."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Mean count is 6 per 0.25 m². Estimate number in 100 m².", "a": 2400, "unit": "", "tol": 0.005, "why": "6/0.25 × 100 = 2400."}, {"q": "Why use random quadrat coordinates?", "opts": ["To force identical counts", "To avoid repeats", "To reduce selection bias"], "a": 2, "why": "To reduce selection bias"}], "exam": [{"q": "Describe estimating daisies in a field.", "m": 3, "ms": ["Use random coordinates and a consistent quadrat counting rule.", "Take many samples and calculate mean density for the known quadrat area.", "Multiply density by measured total field area."]}], "sim": "sampling", "practical": {"title": "Required practical 9 · Population size and distribution", "method": ["Measure habitat area and use random coordinates for abundance quadrats.", "Count a selected species consistently across many quadrats.", "For distribution, place quadrats along repeated transects and measure a relevant abiotic factor."], "variables": ["Keep quadrat dimensions and counting rules constant.", "Record environmental measurements alongside abundance.", "Repeat across habitat areas or transects."], "safety": ["Check terrain, weather and site-access risks.", "Avoid disturbing wildlife and wash hands after fieldwork."], "analysis": "Mean count ÷ quadrat area estimates density; multiply by total area for population. Transects test gradients and do not replace random sampling for unbiased whole-area estimates."}}, {"id": "b-cycles", "unit": "ecology", "title": "Carbon and water cycles", "spec": "4.7.2.2", "paper": [2], "tier": "all", "separate": false, "summary": "Photosynthesis incorporates atmospheric carbon into biomass; feeding passes it between organisms.", "notes": [{"title": "Understand the biology", "html": "<p>Photosynthesis incorporates atmospheric carbon into biomass; feeding passes it between organisms. Respiration by plants, animals and decomposers returns carbon dioxide. Decomposition returns mineral ions to soil; combustion releases stored carbon dioxide. Matter is recycled rather than created.<\/p>"}, {"title": "Apply and explain", "html": "<p>Evaporation and transpiration transfer water to air, condensation forms clouds and precipitation returns it. Runoff and soil movement return water to rivers and oceans. Materials cycle, whereas energy eventually dissipates to surroundings and is not recycled in the same way.<\/p>"}], "keypoints": ["Photosynthesis incorporates atmospheric carbon into biomass; feeding passes it between organisms.", "Evaporation and transpiration transfer water to air, condensation forms clouds and precipitation returns it."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which removes atmospheric carbon dioxide?", "opts": ["Photosynthesis", "Combustion", "Respiration"], "a": 0, "why": "Photosynthesis"}, {"q": "Decomposers return to soil…", "opts": ["Mineral ions", "Sunlight", "Newly created atoms"], "a": 0, "why": "Mineral ions"}], "exam": [{"q": "Explain how carbon in a dead leaf can enter a growing plant.", "m": 3, "ms": ["Decomposers break down the leaf and respire.", "Respiration releases carbon dioxide to the air.", "A plant absorbs and fixes that carbon in photosynthesis."]}]}, {"id": "b-biodiversity", "unit": "ecology", "title": "Biodiversity, pollution and land use", "spec": "4.7.3.1–4.7.3.4", "paper": [2], "tier": "all", "separate": false, "summary": "Biodiversity is the variety of species.", "notes": [{"title": "Understand the biology", "html": "<p>Biodiversity is the variety of species. It supports stable food webs and resources such as food and potential medicines. Human population growth and consumption increase waste, including sewage, fertilisers, toxic chemicals, smoke and acidic gases.<\/p>"}, {"title": "Apply and explain", "html": "<p>Farming, building, quarrying and waste disposal can destroy habitats. Deforestation reduces habitats and releases carbon through burning or decay. Peat stores partly decomposed carbon; draining or extracting it damages habitats and releases carbon dioxide. Explain both ecological effects and the demands driving land use.<\/p>"}], "keypoints": ["Biodiversity is the variety of species.", "Farming, building, quarrying and waste disposal can destroy habitats."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Biodiversity means…", "opts": ["Amount of rainfall", "Variety of species", "Count of only one species"], "a": 1, "why": "Variety of species"}, {"q": "Why can peat extraction increase carbon dioxide?", "opts": ["It stops every organism respiring", "Stored carbon is released during decay or burning", "Peat contains no carbon"], "a": 1, "why": "Stored carbon is released during decay or burning"}], "exam": [{"q": "Explain environmental effects of draining a peat bog.", "m": 3, "ms": ["Habitat destruction can reduce biodiversity.", "Exposed peat decomposes or burns, releasing carbon dioxide.", "Added carbon dioxide contributes to the enhanced greenhouse effect."]}]}, {"id": "b-conservation", "unit": "ecology", "title": "Climate and maintaining biodiversity", "spec": "4.7.3.5–4.7.3.6", "paper": [2], "tier": "all", "separate": false, "summary": "Increasing greenhouse gases contribute to higher global temperature.", "notes": [{"title": "Understand the biology", "html": "<p>Increasing greenhouse gases contribute to higher global temperature. Changing climate can alter distribution, migration and food availability and increase extinction risk. Distinguish long-term trends from daily weather, and consider uncertainty and time span when interpreting evidence.<\/p>"}, {"title": "Apply and explain", "html": "<p>Breeding programmes, protected habitats, restoration, hedgerows and field margins can support biodiversity. Reducing deforestation, emissions and waste can reduce damage. Compare ecological benefits with cost, housing or food-production needs to make a reasoned judgement.<\/p>"}], "keypoints": ["Increasing greenhouse gases contribute to higher global temperature.", "Breeding programmes, protected habitats, restoration, hedgerows and field margins can support biodiversity."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which supports habitat connectivity?", "opts": ["Removing every field margin", "Draining ponds", "Restoring hedgerows"], "a": 2, "why": "Restoring hedgerows"}, {"q": "Why does one cold day not disprove warming?", "opts": ["Temperature cannot be measured", "All thermometers fail", "Weather varies while climate uses long-term data"], "a": 2, "why": "Weather varies while climate uses long-term data"}], "exam": [{"q": "Evaluate restoring wetland on agricultural land.", "m": 3, "ms": ["It can restore habitats and biodiversity / carbon storage.", "It may reduce agricultural land or income.", "A judgement should weigh local ecological benefit against food and cost implications."]}]}, {"id": "b-decay", "unit": "ecology", "title": "Decomposition, compost and biogas", "spec": "4.7.2.3", "paper": [2], "tier": "all", "separate": true, "summary": "Decomposer activity depends on moisture, oxygen and temperature.", "notes": [{"title": "Understand the biology", "html": "<p>Decomposer activity depends on moisture, oxygen and temperature. Warming increases enzyme activity up to an optimum; excessive heat denatures enzymes. Aerating compost supports aerobic decomposition, returning useful nutrients to soil.<\/p>"}, {"title": "Apply and explain", "html": "<p>Milk decay can be followed through falling pH as microorganisms produce acids. Compare time for a defined change at controlled temperatures. Anaerobic decay in biogas generators produces methane fuel. A pH-change rate is a proxy, not a direct bacterial count.<\/p>"}], "keypoints": ["Decomposer activity depends on moisture, oxygen and temperature.", "Milk decay can be followed through falling pH as microorganisms produce acids."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "A fixed pH change takes 40 min. Calculate 1/time.", "a": 0.025, "unit": "min⁻¹", "tol": 0.005, "why": "1/40 = 0.025."}, {"q": "Why turn compost?", "opts": ["To improve oxygen availability", "To remove every decomposer", "To prevent gas exchange"], "a": 0, "why": "To improve oxygen availability"}], "exam": [{"q": "Why can decay be slow in both cold and very hot conditions?", "m": 3, "ms": ["Cold reduces enzyme-controlled reaction rates.", "Very high heat denatures enzymes / kills decomposers.", "Both reduce microbial breakdown of biological material."]}], "practical": {"title": "Required practical 10 · Temperature and milk decay", "method": ["Use the teacher-approved milk preparation with a suitable pH measurement method.", "Hold samples at controlled temperatures and measure pH at regular intervals or time to a fixed pH change.", "Repeat at each temperature with equal starting conditions."], "variables": ["Independent: temperature.", "Dependent: pH-change rate or reciprocal endpoint time.", "Control milk composition, volume, starting pH and microorganism source."], "safety": ["Never taste samples; avoid contact with cultures.", "Follow school biological-waste disposal and hot-water-bath procedures."], "analysis": "Compare means and uncertainty. Acid production causes the pH fall; this is a proxy for decay, not a direct count of all microorganisms."}}, {"id": "b-biomass", "unit": "ecology", "title": "Trophic levels and biomass efficiency", "spec": "4.7.4", "paper": [2], "tier": "all", "separate": true, "summary": "Producers occupy trophic level 1 followed by primary, secondary and tertiary consumers.", "notes": [{"title": "Understand the biology", "html": "<p>Producers occupy trophic level 1 followed by primary, secondary and tertiary consumers. Biomass pyramids compare dry mass at a stated time. Less biomass reaches higher levels because not all is eaten, some is undigested and respiration releases carbon dioxide.<\/p>"}, {"title": "Apply and explain", "html": "<p>Efficiency = biomass transferred ÷ biomass available × 100. A transfer of 600 kg from 8000 kg is 7.5%. Energy transfers to surroundings rather than being destroyed. Do not assume every ecosystem has the same efficiency or confuse dry biomass with organism number.<\/p>"}], "keypoints": ["Producers occupy trophic level 1 followed by primary, secondary and tertiary consumers.", "Efficiency = biomass transferred ÷ biomass available × 100."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "50 kg transfers from a level with 500 kg. Calculate efficiency.", "a": 10, "unit": "%", "tol": 0.005, "why": "50/500 × 100 = 10%."}, {"q": "Which reduces biomass available to the next level?", "opts": ["Predators photosynthesising", "Respiration releasing carbon dioxide", "Every molecule being absorbed"], "a": 1, "why": "Respiration releasing carbon dioxide"}], "exam": [{"q": "Explain decreasing biomass at higher trophic levels.", "m": 3, "ms": ["Some material is not eaten.", "Some eaten material is not digested and is egested.", "Respiration releases carbon dioxide and transfers energy to surroundings."]}]}, {"id": "b-foodproduction", "unit": "ecology", "title": "Food security and sustainable production", "spec": "4.7.5", "paper": [2], "tier": "all", "separate": true, "summary": "Food security means access to sufficient safe nutritious food.", "notes": [{"title": "Understand the biology", "html": "<p>Food security means access to sufficient safe nutritious food. Population growth, climate, pests, disease, conflict and costs influence supply and access. Fishing quotas and suitable net sizes allow populations to reproduce. Increased production alone does not guarantee fair distribution.<\/p>"}, {"title": "Apply and explain", "html": "<p>Controlled livestock conditions can reduce energy used in movement and warming but raise welfare concerns. Fermenters produce fungal mycoprotein; modified crops may improve nutrition or resistance. Evaluate output, resource use, emissions, welfare and cost rather than assuming a single solution works everywhere.<\/p>"}, {"title": "Mycoprotein and improved nutrition", "html": "<p>Fusarium fungus can grow aerobically on a carbohydrate feed in a fermenter, supplying protein-rich food. Controlled oxygen, temperature and nutrient supply support growth; harvested biomass is processed for food. Genetically modified crops can also improve nutritional content, such as enhanced vitamin precursors, but suitability depends on the dietary problem and local evidence.<\/p>"}], "keypoints": ["Food security means access to sufficient safe nutritious food.", "Controlled livestock conditions can reduce energy used in movement and warming but raise welfare concerns."], "mistakes": ["Explain the biological mechanism as well as naming it.", "Use the conditions and data given; avoid claiming that one observed trend applies in every situation."], "checks": [{"q": "Which can support sustainable fishing?", "opts": ["Catching every breeding adult", "Always using the smallest mesh", "Suitable catch quotas"], "a": 2, "why": "Suitable catch quotas"}, {"q": "Why can restricted movement increase livestock growth?", "opts": ["Respiration stops", "Food becomes a hormone", "Less energy is used in movement"], "a": 2, "why": "Less energy is used in movement"}], "exam": [{"q": "Evaluate intensive indoor livestock production.", "m": 3, "ms": ["Controlled temperature / movement can increase growth efficiency.", "Welfare, disease or resource-use concerns must be considered.", "A justified judgement weighs food yield against costs and alternatives."]}]}], "sources": [{"title": "AQA GCSE Biology 8461 specification", "url": "https://www.aqa.org.uk/subjects/biology/gcse/biology-8461/specification"}, {"title": "AQA Combined Science Trilogy biology content", "url": "https://www.aqa.org.uk/subjects/science/gcse/science-8464/specification/biology-subject-content"}, {"title": "AQA Biology required practicals", "url": "https://www.aqa.org.uk/subjects/biology/gcse/biology-8461/specification/practical-assessment"}]};
window.PAPERS=[{"id": "separate-biology-1-foundation", "title": "Biology Paper 1 — Foundation · Original practice", "subject": "Biology", "paper": 1, "tier": "Foundation", "minutes": 105, "marks": 100, "coverage": ["Cell biology", "Organisation", "Infection and response", "Bioenergetics", "Separate Biology content"], "questions": [{"title": "Viewing leaf cells", "topic": "Cell biology", "stem": "A student observes leaf cells with a light microscope. A drawing of one cell is 36 mm long. The actual cell is 0.09 mm long.", "parts": [{"q": "Name the structure that contains genetic material and the structure where photosynthesis occurs.", "m": 2, "ms": ["Nucleus (1).", "Chloroplast (1)."]}, {"q": "Calculate the magnification of the drawing. Show your working.", "m": 2, "ms": ["Magnification = image size / actual size (1).", "36 / 0.09 = 400 (1)."], "answer": 400, "unit": "times", "tolerance": 1e-06}, {"q": "Describe how to prepare a thin leaf sample on a microscope slide.", "m": 3, "ms": ["Place a thin sample in a drop of water on a slide (1).", "Lower a coverslip gently at an angle to reduce trapped air (1).", "Remove excess water and begin observing with low-power objective (1)."]}, {"q": "Give three differences between a bacterial cell and a leaf cell.", "m": 3, "ms": ["Bacteria lack a nucleus; leaf cells have one (1).", "Bacteria have no chloroplasts; photosynthetic leaf cells have chloroplasts (1).", "Bacteria have no mitochondria; leaf cells have mitochondria (1). Accept bacterial circular DNA/plasmids versus chromosomes in a nucleus as an alternative distinct difference."]}]}, {"title": "Osmosis in potato cylinders", "topic": "Cell biology", "stem": "<table><thead><tr><th>Solution<\/th><th>Initial mass / g<\/th><th>Final mass / g<\/th><\/tr><\/thead><tbody><tr><td>Water<\/td><td>4<\/td><td>4.8<\/td><\/tr><tr><td>Concentrated sugar solution<\/td><td>4<\/td><td>3.6<\/td><\/tr><\/tbody><\/table>", "parts": [{"q": "Calculate the increase in mass of the cylinder in water.", "m": 2, "ms": ["4.8 - 4.0 (1).", "0.8 g (1)."], "answer": 0.8, "unit": "g", "tolerance": 1e-06}, {"q": "Calculate the percentage increase in mass of this cylinder.", "m": 2, "ms": ["0.8 / 4.0 x 100 (1).", "20% (1)."], "answer": 20, "unit": "%", "tolerance": 1e-06}, {"q": "Explain why the cylinder in concentrated sugar solution loses mass.", "m": 3, "ms": ["Water moves out of potato cells (1).", "Through partially permeable membranes (1).", "By osmosis, from a more dilute solution inside to a more concentrated solution outside (1)."]}, {"q": "Describe three controls or improvements that make this comparison more reliable.", "m": 3, "ms": ["Use cylinders of equal dimensions/from the same potato (1).", "Use the same immersion time and temperature (1).", "Repeat with several cylinders and calculate means; or blot each cylinder consistently before weighing (1)."]}]}, {"title": "Enzymes and digestion", "topic": "Organisation", "stem": "Amylase digests starch. In a test at 35 °C, starch takes 120 seconds to disappear. At 45 °C it takes 60 seconds.", "parts": [{"q": "Name the product type made by amylase and the reagent used to test for starch.", "m": 2, "ms": ["Sugars (1).", "Iodine solution (1)."]}, {"q": "Calculate the ratio of the time at 35 °C to the time at 45 °C. Give the simplest whole-number ratio.", "m": 2, "ms": ["120:60 (1).", "2:1 (1)."]}, {"q": "Explain how bile helps the digestion of fats.", "m": 3, "ms": ["Neutralises stomach acid in the small intestine (1).", "Provides alkaline conditions for enzymes (1).", "Emulsifies fats into small droplets, increasing surface area for lipase (1)."]}, {"q": "Explain why amylase works very slowly at 80 °C.", "m": 3, "ms": ["High temperature changes the shape of the enzyme/active site (1).", "The substrate no longer fits the active site (1).", "The enzyme is denatured, so fewer enzyme-substrate complexes form (1)."]}]}, {"title": "Transport in the body", "topic": "Organisation", "stem": "Blood circulates between the heart, lungs and body tissues.", "parts": [{"q": "Name the blood component that carries oxygen and the component involved in clotting.", "m": 2, "ms": ["Red blood cells (1).", "Platelets (1)."]}, {"q": "Explain why the left ventricle has a thicker muscular wall than the right ventricle.", "m": 2, "ms": ["Left ventricle pumps blood around the whole body (1).", "Needs to generate higher pressure than the right ventricle, which pumps to nearby lungs (1)."]}, {"q": "Explain three features of alveoli that make gas exchange effective.", "m": 3, "ms": ["Large surface area increases exchange (1).", "Thin walls provide short diffusion distance (1).", "Good blood supply/ventilation maintains a concentration gradient (1)."]}, {"q": "Describe how coronary heart disease develops and one treatment.", "m": 3, "ms": ["Fatty deposits build up in coronary arteries (1).", "Reduced blood flow reduces oxygen supply to heart muscle (1).", "Stent holds artery open or statins lower blood cholesterol and slow deposit formation (1)."]}]}, {"title": "Preventing infectious disease", "topic": "Infection and response", "stem": "A school has 800 pupils. Following a vaccination programme, 680 pupils are vaccinated.", "parts": [{"q": "Calculate the percentage of pupils vaccinated.", "m": 2, "ms": ["680 / 800 x 100 (1).", "85% (1)."], "answer": 85, "unit": "%", "tolerance": 1e-06}, {"q": "State one bacterial disease and one viral disease from the course.", "m": 2, "ms": ["Salmonella food poisoning or gonorrhoea (1).", "Measles, HIV or tobacco mosaic virus (1)."]}, {"q": "Explain how vaccination reduces the risk of becoming ill after later exposure to a pathogen.", "m": 6, "ms": ["Vaccine introduces dead/inactive pathogen or pathogen antigens.", "Antigens stimulate white blood cells.", "White blood cells produce specific antibodies.", "Some white blood cells remain as memory cells.", "On later exposure the specific antibodies are produced faster.", "Antibodies destroy the pathogen before it causes serious illness. Accept a valid explanation of reduced transmission protecting unvaccinated people as an alternative final point."], "note": "Award one mark for each distinct valid linked point, maximum 6."}]}, {"title": "Photosynthesis in pondweed", "topic": "Bioenergetics", "stem": "<table><thead><tr><th>Lamp distance / cm<\/th><th>Bubbles in 1 minute<\/th><\/tr><\/thead><tbody><tr><td>10<\/td><td>44<\/td><\/tr><tr><td>20<\/td><td>22<\/td><\/tr><tr><td>30<\/td><td>12<\/td><\/tr><\/tbody><\/table>", "parts": [{"q": "Name the gas in the bubbles and the organelle that absorbs light.", "m": 2, "ms": ["Oxygen (1).", "Chloroplast (1)."]}, {"q": "Calculate the decrease in bubbles per minute between 10 cm and 30 cm.", "m": 2, "ms": ["44 - 12 (1).", "32 bubbles per minute (1)."], "answer": 32, "unit": "bubbles/min", "tolerance": 1e-06}, {"q": "Explain the pattern in the table.", "m": 3, "ms": ["Light intensity decreases as lamp distance increases (1).", "Less light energy is available for photosynthesis (1).", "Photosynthesis rate decreases, so fewer oxygen bubbles are produced each minute (1)."]}, {"q": "Suggest three improvements to the method.", "m": 3, "ms": ["Collect gas volume rather than count unequal bubbles (1).", "Keep temperature constant using a water bath/heat shield (1).", "Repeat each distance and calculate a mean; or control carbon dioxide with the same bicarbonate solution (1)."]}]}, {"title": "Respiration during exercise", "topic": "Bioenergetics", "stem": "A runner starts a fast sprint. Their muscles need more energy.", "parts": [{"q": "Complete the word equation for aerobic respiration: glucose + ____ → ____ + water.", "m": 2, "ms": ["Oxygen (1).", "Carbon dioxide (1)."]}, {"q": "State two changes to the body during exercise that deliver more oxygen to muscles.", "m": 2, "ms": ["Heart rate increases (1).", "Breathing rate and/or depth increases (1)."]}, {"q": "Compare aerobic and anaerobic respiration in human muscles.", "m": 3, "ms": ["Aerobic uses oxygen; anaerobic does not (1).", "Anaerobic forms lactic acid; aerobic forms carbon dioxide and water (1).", "Anaerobic transfers less energy per glucose molecule (1)."]}, {"q": "Explain why breathing remains fast for a while after the sprint.", "m": 3, "ms": ["Lactic acid accumulated when oxygen supply was insufficient (1).", "Extra oxygen is needed to react with/remove accumulated lactic acid (1).", "This extra oxygen requirement is the oxygen debt (1)."]}]}, {"title": "Comparing antiseptics", "stem": "<p>Students use a teacher-approved bacterial culture on agar. Equal paper discs contain antiseptic A, antiseptic B or sterile water. Mean clear-zone diameters are A: 12 mm; B: 8 mm; water: 0 mm.<\/p>", "topic": "Culturing microorganisms", "parts": [{"q": "Explain why the agar and inoculating equipment should be sterile.", "m": 2, "ms": ["Sterilisation removes unwanted microorganisms.", "This reduces contamination so growth reflects the intended bacterial culture."]}, {"q": "Give two controlled variables, other than disc size.", "m": 2, "ms": ["Use the same bacterial species / starting concentration.", "Keep agar depth, incubation temperature or incubation time the same (one additional valid control)."]}, {"q": "Use π = 3.14 to calculate the area of A’s clear circular zone.", "m": 3, "ms": ["Radius = 12/2 = 6 mm.", "Area = πr² = 3.14 × 36.", "Area = 113.04 mm²."], "answer": 113.04, "unit": "mm²"}, {"q": "State a conclusion, its supporting evidence, and one reason to repeat the investigation.", "m": 3, "ms": ["A inhibits growth more than B under the tested conditions.", "A has a larger clear zone than B; the water control has none.", "Repeats allow a mean and identification of variation / anomalous results."]}]}, {"title": "Investigating yellow leaves", "stem": "<p>Tomato plants have yellow leaves and slow growth. No pathogen has yet been identified. Group 1 receives a complete mineral solution; group 2 receives an identical solution without magnesium. All other conditions are kept equal.<\/p>", "topic": "Plant disease and mineral deficiency", "parts": [{"q": "Explain why a yellow leaf does not by itself prove infection.", "m": 2, "ms": ["Several conditions can cause yellowing.", "A mineral deficiency rather than a pathogen may be responsible."]}, {"q": "Explain why lacking magnesium can reduce growth.", "m": 3, "ms": ["Magnesium is required for chlorophyll production.", "Less chlorophyll reduces light absorption / photosynthesis.", "Less glucose is available to make biomass / support growth."]}, {"q": "State three controls for the comparison.", "m": 3, "ms": ["Use the same plant species and similar starting age / size.", "Provide the same light and temperature (one valid environmental control).", "Provide equal solution volumes and all other mineral concentrations."]}, {"q": "Suggest a useful additional diagnostic method and explain its purpose.", "m": 2, "ms": ["Use a suitable laboratory test / pathogen identification or validated antibody test.", "It can identify or provide evidence of a particular pathogen rather than relying on symptoms alone."]}]}, {"title": "Defending plants", "stem": "<p>A leaf-eating mammal attacks plants with soft leaves. A second plant has thorns and contains a toxic chemical. A third plant has damaged bark and a fungal infection.<\/p>", "topic": "Plant defences", "parts": [{"q": "Explain how thorns and a toxic chemical can reduce damage.", "m": 3, "ms": ["Thorns can deter or injure herbivores, reducing feeding.", "Toxic chemicals can poison / deter herbivores.", "Reduced feeding preserves tissues needed for growth / photosynthesis."]}, {"q": "Describe two physical barriers, other than thorns, and explain one of their effects.", "m": 3, "ms": ["Cellulose cell walls provide a physical barrier.", "Waxy cuticle or bark provides another physical barrier.", "A barrier reduces pathogen entry into plant tissues."]}, {"q": "Explain why bark damage can increase infection risk.", "m": 2, "ms": ["Damage breaches a physical barrier.", "Fungal pathogens can enter exposed tissues more easily."]}, {"q": "Give two ways a plant can defend itself after infection or attack.", "m": 2, "ms": ["Produce antibacterial chemicals / defensive poisons.", "Shed infected leaves or use another valid specified defence such as curling leaves."]}]}]}, {"id": "separate-biology-1-higher", "title": "Biology Paper 1 — Higher · Original practice", "subject": "Biology", "paper": 1, "tier": "Higher", "minutes": 105, "marks": 100, "coverage": ["Cell biology", "Organisation", "Infection and response", "Bioenergetics", "Separate Biology content"], "questions": [{"title": "Exchange surfaces and cell size", "topic": "Cell biology", "stem": "Model cells are cubes. Cube A has side length 1 mm; cube B has side length 3 mm. Surface area of a cube = 6 × side²; volume = side³.", "parts": [{"q": "Calculate the surface-area-to-volume ratio of cube B.", "m": 3, "ms": ["Surface area = 6 x 9 = 54 mm² (1).", "Volume = 27 mm³ (1).", "Ratio = 2:1 (1)."]}, {"q": "Explain why diffusion alone may be insufficient for a large multicellular organism.", "m": 3, "ms": ["Smaller surface-area-to-volume ratio than a small organism (1).", "Longer internal diffusion distances (1).", "Diffusion cannot supply all cells rapidly enough to meet demand for oxygen/nutrients (1)."]}, {"q": "A micrograph is 72 mm wide at ×600. Calculate the real width in micrometres.", "m": 2, "ms": ["72 / 600 = 0.12 mm (1).", "120 micrometres (1)."], "answer": 120, "unit": "µm", "tolerance": 1e-06}, {"q": "Explain how active transport differs from diffusion.", "m": 2, "ms": ["Active transport moves substances against their concentration gradient; diffusion is down it (1).", "Active transport requires energy from respiration; diffusion does not (1)."]}]}, {"title": "Interpreting an osmosis investigation", "topic": "Cell biology", "stem": "<table><thead><tr><th>Sugar concentration / mol dm⁻³<\/th><th>Mean mass change / %<\/th><\/tr><\/thead><tbody><tr><td>0.2<\/td><td>6<\/td><\/tr><tr><td>0.3<\/td><td>2<\/td><\/tr><tr><td>0.4<\/td><td>-2<\/td><\/tr><tr><td>0.5<\/td><td>-7<\/td><\/tr><\/tbody><\/table>", "parts": [{"q": "Estimate the concentration giving no net mass change by linear interpolation between 0.3 and 0.4 mol dm⁻³.", "m": 2, "ms": ["Zero lies halfway between +2 and -2 (1).", "0.35 mol dm⁻³ (1)."], "answer": 0.35, "unit": "mol dm⁻³", "tolerance": 1e-06}, {"q": "A cylinder initially has mass 5.50 g and loses 7% of its mass. Calculate its final mass.", "m": 3, "ms": ["Mass loss = 5.50 x 0.07 (1).", "Mass loss = 0.385 g (1).", "Final mass = 5.115 g; accept 5.12 g (1)."], "answer": 5.115, "unit": "g", "tolerance": 0.01}, {"q": "Explain why zero net mass change does not mean water molecules have stopped moving.", "m": 2, "ms": ["Water still moves in both directions through the membrane (1).", "Equal average rates produce no net transfer (1)."]}, {"q": "Identify a possible systematic error and explain a practical improvement and its benefit.", "m": 3, "ms": ["Valid systematic error such as consistently leaving surface solution on cylinders before weighing (1).", "Blot each cylinder using a standard procedure (1).", "Reduces bias caused by measuring surface solution rather than tissue mass (1). Accept another coherent error-improvement-benefit sequence."]}]}, {"title": "Enzyme evidence", "topic": "Organisation", "stem": "<table><thead><tr><th>pH<\/th><th>Time for starch to disappear / s<\/th><\/tr><\/thead><tbody><tr><td>4<\/td><td>180<\/td><\/tr><tr><td>6<\/td><td>60<\/td><\/tr><tr><td>7<\/td><td>30<\/td><\/tr><tr><td>9<\/td><td>120<\/td><\/tr><\/tbody><\/table>", "parts": [{"q": "Using rate = 1/time, calculate the reaction rate at pH 7 to 3 significant figures.", "m": 2, "ms": ["1 / 30 (1).", "0.0333 s⁻¹ (1)."], "answer": 0.03333333333333333, "unit": "s⁻¹", "tolerance": 0.0001}, {"q": "Calculate how many times faster the reaction is at pH 7 than at pH 4.", "m": 2, "ms": ["(1/30) / (1/180), or 180/30 (1).", "6 times (1)."], "answer": 6, "unit": "times", "tolerance": 1e-06}, {"q": "Explain the effect of pH on enzyme activity.", "m": 3, "ms": ["Changes in pH can alter the active-site shape (1).", "Substrate becomes less complementary (1).", "Fewer enzyme-substrate complexes form; sufficiently extreme pH can denature the enzyme (1)."]}, {"q": "Explain why temperature, enzyme concentration and starch concentration must each be controlled.", "m": 3, "ms": ["Temperature affects collision rate/denaturation (1).", "Enzyme concentration affects the number of available active sites (1).", "Starch concentration affects collision frequency/substrate availability, so changes could confound the pH comparison (1)."]}]}, {"title": "Heart disease and evidence", "topic": "Organisation", "stem": "In a study, 18 of 300 people in group A developed heart disease, compared with 45 of 300 in group B. Group A took part in an exercise programme. The groups were not randomly allocated.", "parts": [{"q": "Calculate the percentage developing heart disease in group A.", "m": 2, "ms": ["18 / 300 x 100 (1).", "6% (1)."], "answer": 6, "unit": "%", "tolerance": 1e-06}, {"q": "Explain why the study does not prove that exercise alone caused the difference.", "m": 2, "ms": ["Groups may differ in other risk factors such as diet/smoking/age (1).", "These confounding factors could explain part/all of the difference (1)."]}, {"q": "Explain how the heart and blood vessels maintain effective delivery of oxygen to body tissues.", "m": 6, "ms": ["Double circulation sends blood to lungs and then to body.", "Right ventricle pumps deoxygenated blood to lungs.", "Oxygen enters blood at alveoli.", "Left ventricle produces high pressure for circulation to body tissues.", "Arteries carry blood away from heart and withstand high pressure.", "Capillaries have thin walls enabling short diffusion distance into tissues. Accept valves preventing backflow or red cells carrying oxygen using haemoglobin as alternative relevant points."], "note": "Award one mark per distinct relevant linked point, maximum 6."}]}, {"title": "Infection and immunity", "topic": "Infection and response", "stem": "A viral infection causes symptoms in some patients. A doctor explains that antibiotics will not cure the viral infection.", "parts": [{"q": "Explain why antibiotics are ineffective against viruses.", "m": 2, "ms": ["Antibiotics target bacterial structures/processes (1).", "Viruses reproduce inside host cells and do not have the same targets (1)."]}, {"q": "Describe three ways white blood cells defend the body against pathogens.", "m": 3, "ms": ["Phagocytosis/engulfing pathogens (1).", "Producing specific antibodies (1).", "Producing antitoxins to neutralise toxins (1)."]}, {"q": "Explain how antibiotic resistance can increase in a bacterial population.", "m": 3, "ms": ["Mutation produces a resistant bacterium/variation already exists (1).", "Antibiotic kills susceptible bacteria, leaving resistant bacteria (1).", "Resistant bacteria reproduce and pass on resistance, increasing its frequency (1)."]}, {"q": "Give two reasons why a new drug is tested before use in patients.", "m": 2, "ms": ["Determine toxicity/safety (1).", "Determine effectiveness or an appropriate dose (1)."]}]}, {"title": "Limiting photosynthesis", "topic": "Bioenergetics", "stem": "At a fixed temperature, a plant absorbs 2.4 mg of carbon dioxide in 4 minutes at light setting A and 4.8 mg in 4 minutes at setting B. Doubling the light again gives no further increase.", "parts": [{"q": "Calculate the carbon dioxide uptake rate at setting B.", "m": 2, "ms": ["4.8 / 4 (1).", "1.2 mg/min (1)."], "answer": 1.2, "unit": "mg/min", "tolerance": 1e-06}, {"q": "Calculate the percentage increase in uptake from A to B.", "m": 2, "ms": ["(4.8 - 2.4) / 2.4 x 100 (1).", "100% (1)."], "answer": 100, "unit": "%", "tolerance": 1e-06}, {"q": "Explain why doubling light beyond B may give no further increase.", "m": 3, "ms": ["Light is no longer the limiting factor (1).", "Carbon dioxide concentration or temperature may limit the rate (1).", "Increasing that limiting factor, within a suitable range, would allow rate to increase (1)."]}, {"q": "A grower proposes heating the greenhouse all night to increase photosynthesis. Evaluate this proposal.", "m": 3, "ms": ["No photosynthesis without light at night (1).", "Heating costs money/energy and may not raise yield enough to cover costs (1).", "It may be useful only with lighting and sufficient carbon dioxide, or for preventing cold damage; conclusion must link to conditions (1)."]}]}, {"title": "Metabolism and exercise", "topic": "Bioenergetics", "stem": "A person runs at increasing speed until oxygen delivery can no longer meet demand.", "parts": [{"q": "Explain the relationship between respiration and metabolism.", "m": 2, "ms": ["Respiration transfers energy from glucose (1).", "This energy supports metabolic reactions such as protein synthesis or conversion of glucose to glycogen (1)."]}, {"q": "Explain why anaerobic respiration leads to muscle fatigue and an oxygen debt.", "m": 3, "ms": ["Glucose is incompletely broken down to lactic acid (1).", "Lactic acid accumulation contributes to fatigue (1).", "Extra oxygen is required after exercise to react with/remove the lactic acid (1)."]}, {"q": "Describe how lactic acid is processed after exercise.", "m": 3, "ms": ["Transported in blood from muscles to liver (1).", "Converted back into glucose in the liver (1).", "Oxygen/energy is required during recovery; accept some glucose stored as glycogen (1)."]}, {"q": "Compare anaerobic respiration in yeast with that in muscles.", "m": 2, "ms": ["Yeast produces ethanol and carbon dioxide; muscles produce lactic acid (1).", "Both transfer energy without oxygen/from incomplete breakdown of glucose (1)."]}]}, {"title": "Assessing an antiseptic claim", "stem": "<p>An antiseptic company compares equal discs on agar seeded with one approved bacterial strain. Mean inhibition diameters are control: 6 mm; low concentration: 10 mm; high concentration: 14 mm. All discs are 6 mm wide. The company claims its product kills every type of pathogen.<\/p>", "topic": "Microbiology and experimental evidence", "parts": [{"q": "Calculate the clear-zone area outside the high-concentration disc, using π = 3.14.", "m": 3, "ms": ["Outer radius = 7 mm and disc radius = 3 mm.", "Subtract areas: π(7² − 3²).", "Area = 125.6 mm²."], "answer": 125.6, "unit": "mm²"}, {"q": "Explain why the claim is not justified.", "m": 3, "ms": ["Only one bacterial strain was tested, not every pathogen.", "Inhibition of visible growth does not prove all cells were killed.", "The claim extends beyond the experimental conditions / ignores viruses, fungi or other untested pathogens."]}, {"q": "Describe two precautions that reduce contamination and one school incubation precaution.", "m": 3, "ms": ["Sterilise medium / equipment.", "Open lids briefly and use aseptic inoculation.", "Incubate at 25°C and do not reopen incubated plates."]}, {"q": "Why report several independent plates rather than a single plate?", "m": 1, "ms": ["To assess variation and improve reliability of a mean."]}]}, {"title": "Targeted antibody delivery", "stem": "<p>A tumour has antigen X on many of its cells. Scientists make a monoclonal antibody against X and attach a drug. In a trial, 42 of 70 treated patients improve, compared with 21 of 70 receiving the comparison treatment.<\/p>", "topic": "Monoclonal antibodies", "parts": [{"q": "Describe how a hybridoma producing the antibody is made.", "m": 3, "ms": ["Expose a mouse to the antigen and obtain antibody-producing lymphocytes.", "Fuse lymphocytes with tumour cells.", "Select and clone a suitable hybridoma to produce identical antibodies."]}, {"q": "Explain the advantage of attaching the drug to this antibody.", "m": 3, "ms": ["The antibody binds specifically to antigen X.", "Attached drug is delivered to antigen-bearing target cells.", "This may reduce exposure / damage to healthy cells compared with non-targeted delivery."]}, {"q": "Calculate the difference in improvement percentage points.", "m": 3, "ms": ["Treatment: 42/70 × 100 = 60%.", "Comparison: 21/70 × 100 = 30%.", "Difference = 30 percentage points."], "answer": 30, "unit": "percentage points"}, {"q": "Give one reason the improvement data alone do not establish that the treatment is preferable.", "m": 1, "ms": ["Side effects, long-term outcome, cost or comparable trial design must also be evaluated."]}]}, {"title": "Diagnosing a crop problem", "stem": "<p>A crop has yellow leaves. Some plants also have black spots. An agronomist compares magnesium content, performs a pathogen test and investigates whether spraying a fungicide improves growth.<\/p>", "topic": "Plant disease and defences", "parts": [{"q": "Distinguish two possible causes of yellow leaves and explain a growth effect.", "m": 3, "ms": ["Magnesium deficiency can reduce chlorophyll.", "A pathogen can damage photosynthetic tissue.", "Either can reduce photosynthesis and glucose available for growth."]}, {"q": "Explain why a positive pathogen test does not prove every yellow leaf is caused only by that pathogen.", "m": 2, "ms": ["The test identifies presence / a marker, not all causes of every symptom.", "Mineral deficiency or other environmental causes may coexist."]}, {"q": "Design a controlled comparison of the fungicide’s effect.", "m": 3, "ms": ["Randomly allocate similar affected plants to fungicide and control groups.", "Keep nutrient supply, light, water and other conditions constant.", "Repeat with enough plants and compare mean growth using the same measurement interval."]}, {"q": "Explain how an intact cuticle and a defensive chemical can help plants.", "m": 2, "ms": ["A cuticle reduces pathogen entry as a physical barrier.", "A defensive chemical can inhibit microbes or deter herbivores."]}]}]}, {"id": "separate-biology-2-foundation", "title": "Biology Paper 2 — Foundation · Original practice", "subject": "Biology", "paper": 2, "tier": "Foundation", "minutes": 105, "marks": 100, "coverage": ["Homeostasis and response", "Inheritance, variation and evolution", "Ecology", "Separate Biology content"], "questions": [{"title": "Reflexes and reaction time", "topic": "Homeostasis and response", "stem": "Five ruler-drop distances are 16, 18, 15, 17 and 19 cm.", "parts": [{"q": "Calculate the mean distance.", "m": 2, "ms": ["Sum = 85 cm (1).", "85 / 5 = 17 cm (1)."], "answer": 17, "unit": "cm", "tolerance": 1e-06}, {"q": "Name the type of cell that detects a stimulus and the type of cell that carries an impulse to a muscle.", "m": 2, "ms": ["Receptor (1).", "Motor neurone (1)."]}, {"q": "Describe the route taken by an impulse in a reflex arc from a receptor to a muscle.", "m": 3, "ms": ["Sensory neurone carries impulse to central nervous system (1).", "Relay neurone passes impulse within CNS (1).", "Motor neurone carries impulse to the muscle/effector (1)."]}, {"q": "Explain three controls or improvements in a ruler-drop investigation.", "m": 3, "ms": ["Same starting position/zero aligned with fingers (1).", "Same hand/person and posture when comparing conditions (1).", "Repeat and calculate mean; avoid cues by varying delay before release (one valid improvement for 1)."]}]}, {"title": "Blood glucose control", "topic": "Homeostasis and response", "stem": "After a meal, blood glucose concentration rises.", "parts": [{"q": "Name the organ that produces insulin and state how insulin travels to target organs.", "m": 2, "ms": ["Pancreas (1).", "In the blood (1)."]}, {"q": "State two effects of insulin that reduce blood glucose concentration.", "m": 2, "ms": ["Glucose moves from blood into cells (1).", "Glucose is converted to glycogen in liver/muscles (1)."]}, {"q": "Compare Type 1 and Type 2 diabetes.", "m": 3, "ms": ["Type 1 pancreas produces little/no insulin (1).", "Type 2 body cells respond less effectively to insulin (1).", "Type 1 often treated with insulin injections; Type 2 often managed with controlled carbohydrate diet and exercise (1)."]}, {"q": "Explain why a person with diabetes should use several blood glucose readings rather than one reading to judge control.", "m": 3, "ms": ["Glucose changes during the day (1).", "Meals/exercise affect readings (1).", "Several readings reveal patterns and reduce the influence of an unusual reading (1)."]}]}, {"title": "Hormones and reproduction", "topic": "Homeostasis and response", "stem": "Hormones coordinate the menstrual cycle.", "parts": [{"q": "State where oestrogen is mainly produced and one of its roles in the menstrual cycle.", "m": 2, "ms": ["Ovaries (1).", "Builds/thickens uterus lining (1)."]}, {"q": "Name the hormone that causes ovulation and the hormone that stimulates egg maturation.", "m": 2, "ms": ["LH causes ovulation (1).", "FSH stimulates egg maturation (1)."]}, {"q": "Explain three ways contraception can prevent pregnancy.", "m": 6, "ms": ["Barrier method: a condom or diaphragm forms a physical barrier.", "The barrier prevents sperm reaching the egg, so fertilisation cannot occur.", "Hormonal method: an oral contraceptive supplies reproductive hormones.", "These can inhibit egg maturation or ovulation, so an egg is not available for fertilisation.", "Intrauterine method: an IUD is placed inside the uterus. Accept sterilisation blocking sperm ducts or oviducts as an alternative method.", "The IUD can prevent implantation, impair sperm/fertilisation, or release hormones that thicken cervical mucus. For sterilisation: gametes cannot meet. Award this explanation mark only with the matching method. Do not credit abortion as contraception."], "note": "Award up to 2 marks for each of three distinct methods; maximum 6."}]}, {"title": "Inheritance of a recessive condition", "topic": "Inheritance, variation and evolution", "stem": "A recessive allele d causes a condition. Both parents have genotype Dd. The parents’ gametes are already arranged in this incomplete Punnett square: <table><thead><tr><th>Gametes<\/th><th>D<\/th><th>d<\/th><\/tr><\/thead><tbody><tr><th>D<\/th><td>DD<\/td><td>Box A<\/td><\/tr><tr><th>d<\/th><td>Box B<\/td><td>dd<\/td><\/tr><\/tbody><\/table>", "parts": [{"q": "State the meaning of allele and genotype.", "m": 2, "ms": ["Allele is a version of a gene (1).", "Genotype is the combination of alleles an individual has (1)."]}, {"q": "Complete Box A and Box B in the provided Punnett square.", "m": 2, "ms": ["Box A = Dd (1).", "Box B = Dd (1)."]}, {"q": "Calculate the probability of an offspring having the condition. Give a percentage.", "m": 2, "ms": ["Only dd has the condition; 1 of 4 (1).", "25% (1)."], "answer": 25, "unit": "%", "tolerance": 1e-06}, {"q": "Explain why a dominant allele can be expressed in a heterozygous person, and why this does not mean it is always common in a population.", "m": 4, "ms": ["Heterozygous means two different alleles (1).", "One copy of a dominant allele is sufficient to affect phenotype (1).", "Dominance describes expression, not how frequent an allele is (1).", "Frequency also depends on inheritance, selection and chance/population history (1)."]}]}, {"title": "Selection and biodiversity", "topic": "Inheritance, variation and evolution", "stem": "Some beetles are green and some are brown. Birds find green beetles more easily on dark soil.", "parts": [{"q": "State what is meant by variation and name one environmental cause of variation.", "m": 2, "ms": ["Differences between individuals of a species (1).", "Diet/light/exercise or another valid environmental factor (1)."]}, {"q": "Explain how the proportion of brown beetles could increase over many generations.", "m": 4, "ms": ["There is inherited variation in colour (1).", "Brown beetles are less likely to be eaten (1).", "More survive to reproduce (1).", "They pass alleles for brown colour to offspring, increasing frequency (1)."]}, {"q": "Give two reasons why a species may become extinct.", "m": 2, "ms": ["Environmental change/habitat loss/new predator (one for 1).", "New disease/competition/catastrophic event (a second distinct reason for 1)."]}, {"q": "State two benefits of maintaining biodiversity.", "m": 2, "ms": ["Helps maintain stable ecosystems/interdependence (1).", "Preserves genetic resources/food/medicines or other valid ecosystem service (1)."]}]}, {"title": "Sampling a field", "topic": "Ecology", "stem": "Ten randomly placed quadrats each cover 0.25 m². A total of 60 daisies are counted. The field has area 200 m².", "parts": [{"q": "Calculate the total area sampled.", "m": 2, "ms": ["10 x 0.25 (1).", "2.5 m² (1)."], "answer": 2.5, "unit": "m²", "tolerance": 1e-06}, {"q": "Estimate the number of daisies in the field.", "m": 3, "ms": ["Mean density = 60 / 2.5 (1).", "24 daisies/m² (1).", "24 x 200 = 4800 daisies (1)."], "answer": 4800, "unit": "daisies", "tolerance": 1e-06}, {"q": "Describe how to place quadrats randomly.", "m": 2, "ms": ["Set up numbered coordinates across the field (1).", "Use random numbers to select positions (1)."]}, {"q": "Explain two limitations of this estimate.", "m": 3, "ms": ["Daisies may be unevenly distributed (1).", "Small sampled fraction may not represent the whole field (1).", "Counting/identification or seasonal differences can affect the estimate (1)."]}]}, {"title": "Material cycles", "topic": "Ecology", "stem": "Microorganisms break down dead leaves in a woodland. Water and carbon are continually recycled.", "parts": [{"q": "Name the process by which plants remove carbon dioxide from the atmosphere and the process by which decomposers release it.", "m": 2, "ms": ["Photosynthesis (1).", "Respiration (1)."]}, {"q": "Describe how water from the sea can return to the sea after falling on a woodland.", "m": 3, "ms": ["Water evaporates from the sea and condenses to form clouds (1).", "Precipitation/rain falls onto the woodland (1).", "Water returns by surface runoff/rivers or groundwater flow (1)."]}, {"q": "Describe how carbon from a leaf can return to a new tree.", "m": 3, "ms": ["Decomposers break down leaf material (1).", "Respiration releases carbon dioxide to atmosphere (1).", "New tree absorbs carbon dioxide for photosynthesis, building biomass (1)."]}, {"q": "Suggest two actions that reduce human impacts on biodiversity.", "m": 2, "ms": ["Protect/restore habitats, such as reforestation (1).", "Reduce pollution/waste, conservation breeding, or sustainable resource use (a second valid action for 1)."]}]}, {"title": "Focusing on a book", "stem": "<p>A student looks from a distant tree to a nearby book. Light must be focused on the retina. Another student is short-sighted: distant light focuses in front of the retina.<\/p>", "topic": "The eye", "parts": [{"q": "State the functions of the retina and optic nerve.", "m": 2, "ms": ["The retina contains light-sensitive receptors.", "The optic nerve carries impulses from the eye to the brain."]}, {"q": "Describe how the eye accommodates to the nearby book.", "m": 3, "ms": ["Ciliary muscles contract.", "Suspensory ligaments loosen.", "The lens becomes thicker / refracts light more strongly."]}, {"q": "State how pupil size changes in bright light and explain its benefit.", "m": 2, "ms": ["The pupil becomes smaller.", "Less light enters, protecting the light-sensitive retina."]}, {"q": "Name the correcting lens for short sight and explain where corrected light should focus.", "m": 2, "ms": ["Use a concave lens.", "It refracts the light so the final image is focused on the retina."]}, {"q": "Give one alternative to spectacles for correcting a vision defect.", "m": 1, "ms": ["Contact lenses, appropriate laser surgery or lens replacement."]}]}, {"title": "Treating kidney failure", "stem": "<p>A patient with kidney failure receives dialysis three times a week. A possible transplant would require a donor and medicines to reduce rejection.<\/p>", "topic": "Kidney function and dialysis", "parts": [{"q": "Name the organ that produces urea and the organ that removes it from blood.", "m": 2, "ms": ["Urea is produced in the liver.", "Kidneys remove it from blood."]}, {"q": "Name two useful substances normally reabsorbed by kidneys after filtration.", "m": 2, "ms": ["Glucose.", "An appropriate amount of water or ions."]}, {"q": "Describe the basic action of dialysis.", "m": 3, "ms": ["Blood passes alongside dialysis fluid separated by a partially permeable membrane.", "Urea moves from blood into dialysis fluid down a concentration gradient.", "Blood cells and large proteins are retained."]}, {"q": "Compare a transplant with continuing dialysis.", "m": 3, "ms": ["A successful transplant can give continuous function / avoid repeated dialysis sessions.", "It requires a donor and has surgical / rejection risks.", "Immune-suppressing medicines reduce rejection but increase infection risk."]}]}, {"title": "Light and seedling growth", "stem": "<p>Ten similar seedlings receive light from the left. Ten controls receive light equally from all sides. Both groups receive the same water, temperature and growing medium. After four days, shoots in the first group bend left.<\/p>", "topic": "Plant tropisms", "parts": [{"q": "Name this directional growth response and explain the word positive.", "m": 2, "ms": ["Phototropism.", "Positive means growth towards the light stimulus."]}, {"q": "Explain why the evenly lit control group is useful.", "m": 2, "ms": ["It provides a comparison without directional lighting.", "A difference can therefore be linked more confidently to light direction."]}, {"q": "Give two measurements or records that improve the investigation.", "m": 2, "ms": ["Measure shoot length / change in length.", "Record direction using accurate labelled drawings or a consistent angle measure."]}, {"q": "Explain how plant hormones can cause bending.", "m": 2, "ms": ["Unequal hormone / auxin distribution develops across the shoot.", "The two sides grow at different rates."]}, {"q": "State the usual growth response of a root and shoot to gravity.", "m": 2, "ms": ["Roots grow towards gravity / positive gravitropism.", "Shoots grow against gravity / negative gravitropism."]}]}]}, {"id": "separate-biology-2-higher", "title": "Biology Paper 2 — Higher · Original practice", "subject": "Biology", "paper": 2, "tier": "Higher", "minutes": 105, "marks": 100, "coverage": ["Homeostasis and response", "Inheritance, variation and evolution", "Ecology", "Separate Biology content"], "questions": [{"title": "Comparing nervous and hormonal control", "topic": "Homeostasis and response", "stem": "<table><thead><tr><th>Condition<\/th><th>Reaction time 1 / ms<\/th><th>Reaction time 2 / ms<\/th><th>Reaction time 3 / ms<\/th><\/tr><\/thead><tbody><tr><td>Quiet<\/td><td>210<\/td><td>220<\/td><td>230<\/td><\/tr><tr><td>Distraction<\/td><td>270<\/td><td>280<\/td><td>290<\/td><\/tr><\/tbody><\/table>", "parts": [{"q": "Calculate the percentage increase in mean reaction time with distraction.", "m": 3, "ms": ["Means 220 ms and 280 ms (1).", "Increase = 60 ms; 60/220 x 100 (1).", "27.3% to 3 significant figures (1)."], "answer": 27.3, "unit": "%", "tolerance": 0.1}, {"q": "Explain how an impulse crosses a synapse.", "m": 3, "ms": ["Impulse triggers release of a neurotransmitter (1).", "Chemical diffuses across gap (1).", "Binds to receptors on next neurone and triggers a new electrical impulse (1)."]}, {"q": "Compare nervous and hormonal coordination.", "m": 2, "ms": ["Nervous signals travel along neurones; hormones are carried in blood (1).", "Nervous responses generally faster/shorter lasting and more localised; hormonal responses generally slower/longer lasting (1)."]}, {"q": "Suggest two ways to improve the validity of this comparison.", "m": 2, "ms": ["Test same people in both conditions with order randomised (1).", "Control sleep/caffeine/practice and other distractions, or use more participants (1)."]}]}, {"title": "Negative feedback", "topic": "Homeostasis and response", "stem": "A fasting person has falling blood glucose concentration. For the thyroxine question, use this information: the pituitary releases TSH, which stimulates the thyroid gland to release thyroxine.", "parts": [{"q": "Explain how glucagon restores blood glucose concentration.", "m": 4, "ms": ["Pancreas detects low blood glucose/releases glucagon (1).", "Glucagon travels to liver in blood (1).", "Stimulates conversion of glycogen to glucose (1).", "Glucose released into blood raises concentration (1)."]}, {"q": "Explain why this is negative feedback.", "m": 2, "ms": ["Response opposes the initial fall (1).", "As concentration returns to normal, stimulation/glucagon secretion decreases (1)."]}, {"q": "Explain how adrenaline prepares the body for action.", "m": 2, "ms": ["Increases heart rate (1).", "Increases delivery of oxygen and glucose to muscles for increased respiration (1)."]}, {"q": "Explain how thyroxine secretion is controlled when its concentration becomes too high.", "m": 2, "ms": ["High thyroxine inhibits pituitary release of TSH (1).", "Less TSH stimulates thyroid, reducing thyroxine secretion (1)."]}]}, {"title": "Reproductive hormone interactions", "topic": "Homeostasis and response", "stem": "A clinic treats some cases of infertility with hormones. Success is not guaranteed.", "parts": [{"q": "State the roles of FSH and LH during fertility treatment.", "m": 2, "ms": ["FSH stimulates maturation of eggs (1).", "LH stimulates ovulation/release of an egg (1)."]}, {"q": "Explain how oestrogen and progesterone help regulate the menstrual cycle.", "m": 4, "ms": ["Oestrogen stimulates rebuilding uterus lining (1).", "Oestrogen inhibits FSH and stimulates LH release (1).", "Progesterone maintains uterus lining (1).", "Progesterone inhibits FSH and LH (1)."]}, {"q": "A clinic reports 72 births from 240 treatment cycles. Calculate its birth rate per treatment cycle as a percentage.", "m": 2, "ms": ["72/240 x 100 (1).", "30% (1)."], "answer": 30, "unit": "%", "tolerance": 1e-06}, {"q": "Give one benefit and one risk or disadvantage of IVF.", "m": 2, "ms": ["Can enable an infertile couple to have a child (1).", "Multiple births/hormone side effects/emotional or financial cost; one valid disadvantage (1)."]}]}, {"title": "Meiosis and inheritance", "topic": "Inheritance, variation and evolution", "stem": "A recessive allele a causes a genetic condition. A carrier Aa has a child with a person aa who has the condition.", "parts": [{"q": "Use a genetic cross to find the probability of a child having the condition. Give a decimal probability.", "m": 3, "ms": ["Carrier gametes A and a; affected parent gamete a (1).", "Offspring Aa and aa in equal proportions (1).", "Probability 1/2 or 50% (1)."], "answer": 0.5, "unit": "probability", "tolerance": 1e-06}, {"q": "Explain how meiosis and fertilisation maintain chromosome number across generations.", "m": 3, "ms": ["Meiosis halves chromosome number in gametes (1).", "Fertilisation joins/fuses two gamete nuclei (1).", "Restores the full chromosome number in the zygote (1)."]}, {"q": "Explain why siblings can have different phenotypes even with the same parents.", "m": 2, "ms": ["Sexual reproduction produces different combinations of parental alleles (1).", "Environmental differences can also affect phenotype (1)."]}, {"q": "Evaluate using the result of this cross to predict the outcomes for exactly two children.", "m": 2, "ms": ["Probability applies independently to each conception (1).", "It does not guarantee that exactly one of two children will have the condition (1)."]}]}, {"title": "Antibiotic resistance and genetic engineering", "topic": "Inheritance, variation and evolution", "stem": "A hospital finds that an increasing proportion of bacteria are resistant to an antibiotic.", "parts": [{"q": "Explain how resistance becomes more common and how prescribing decisions can slow this process.", "m": 6, "ms": ["Random mutation creates an allele giving resistance/variation already exists.", "Antibiotic creates a selection pressure.", "Susceptible bacteria are killed.", "Resistant bacteria survive and reproduce rapidly.", "Resistance allele is passed to offspring, increasing its frequency.", "Prescribing antibiotics only when needed reduces selection pressure. Accept completion of the prescribed course as an alternative control, with a correct explanation."], "note": "Award one mark per distinct valid linked point, maximum 6."}, {"q": "Describe how bacteria can be genetically engineered to produce human insulin.", "m": 4, "ms": ["Human insulin gene is isolated using enzymes (1).", "Gene inserted into a vector/plasmid using enzymes (1).", "Vector introduces gene into bacteria (1).", "Modified bacteria are grown and express the gene to produce insulin, which is collected/purified (1)."]}]}, {"title": "Interdependence and sampling", "topic": "Ecology", "stem": "A field has area 800 m². Twenty 0.5 m² quadrats contain a total of 150 clover plants. Fewer clover plants are found near a shaded hedge.", "parts": [{"q": "Estimate the total number of clover plants in the field.", "m": 3, "ms": ["Area sampled = 20 x 0.5 = 10 m² (1).", "Density = 150/10 = 15 plants/m² (1).", "Estimate = 15 x 800 = 12000 plants (1)."], "answer": 12000, "unit": "plants", "tolerance": 1e-06}, {"q": "Design an investigation of the effect of distance from the hedge on clover abundance.", "m": 4, "ms": ["Place a tape/transect perpendicular to hedge (1).", "Sample quadrats at regular measured distances (1).", "Count clover using a consistent inclusion rule and record light intensity/other relevant factor (1).", "Repeat parallel transects and calculate mean abundance at each distance (1)."]}, {"q": "Explain why the association with shade does not prove that light is the only cause.", "m": 3, "ms": ["Other factors may vary with distance (1).", "For example water/mineral availability/trampling/competition (1).", "Need control or additional measurement/manipulation of these variables to test causation (1)."]}]}, {"title": "Carbon and water cycles", "topic": "Ecology", "stem": "A restoration project plants 400 trees. In a simplified model, each tree removes an average of 12 kg carbon dioxide per year. In practice, the value varies with tree age and environmental conditions.", "parts": [{"q": "Calculate the total carbon dioxide removed per year in this model.", "m": 2, "ms": ["400 x 12 (1).", "4800 kg per year (1)."], "answer": 4800, "unit": "kg/year", "tolerance": 1e-06}, {"q": "Explain how carbon from dead leaves can return to the atmosphere.", "m": 2, "ms": ["Microorganisms/decomposers break down dead material (1).", "Their respiration releases carbon dioxide (1)."]}, {"q": "Explain how water is continually recycled between the sea, atmosphere and land.", "m": 3, "ms": ["Evaporation from sea/land and transpiration from plants move water into air (1).", "Water vapour condenses into clouds and falls as precipitation (1).", "Runoff/rivers/groundwater return water to the sea (1)."]}, {"q": "Explain how deforestation can increase atmospheric carbon dioxide.", "m": 3, "ms": ["Fewer trees remove carbon dioxide by photosynthesis (1).", "Burning felled trees releases carbon dioxide (1).", "Decay/respiration of dead biomass also releases carbon dioxide (1)."]}]}, {"title": "Keeping warm and conserving water", "stem": "<p>A runner finishes training in cold dry air. Core temperature falls slightly and blood becomes more concentrated because water has been lost. No water is drunk immediately.<\/p>", "topic": "Thermoregulation and ADH", "parts": [{"q": "Explain how shivering and vasoconstriction oppose the temperature fall.", "m": 4, "ms": ["Shivering involves repeated muscle contraction and increased respiration.", "Energy is transferred to thermal stores.", "Vasoconstriction reduces blood flow near the skin.", "This reduces energy transfer to the surroundings."]}, {"q": "Explain the ADH response to the more concentrated blood.", "m": 4, "ms": ["A change in blood water concentration is detected in the brain.", "The pituitary releases more ADH.", "Kidney tubules become more permeable to water.", "More water is reabsorbed into blood, producing a smaller volume of concentrated urine."]}, {"q": "Explain why this is negative feedback.", "m": 2, "ms": ["The responses oppose the original change in water concentration.", "As conditions return towards normal, the corrective ADH signal decreases."]}]}, {"title": "Researching a brain injury", "stem": "<p>A patient has impaired balance after a brain injury. MRI shows damage near the cerebellum. Researchers consider electrical stimulation during a clinically necessary procedure.<\/p>", "topic": "Brain research and eye accommodation", "parts": [{"q": "State the normal function of the cerebellum and explain one limitation of linking the scan to the symptom.", "m": 2, "ms": ["The cerebellum coordinates movement / balance.", "Connected pathways may also be affected, so the symptom does not isolate one region’s function."]}, {"q": "Evaluate electrical stimulation as evidence for brain function.", "m": 4, "ms": ["A reproducible response can link activation of a region to a function.", "Complex connections mean stimulation may influence other regions.", "Delicate brain tissue creates a risk of irreversible harm.", "Informed consent and likely clinical benefit must justify the procedure."]}, {"q": "The patient looks from a near object to a distant one. Explain accommodation.", "m": 4, "ms": ["Ciliary muscles relax.", "Suspensory ligaments tighten.", "The lens is pulled thinner.", "It refracts light less strongly to focus the distant object on the retina."]}]}, {"title": "Assessing food-production choices", "stem": "<p>A farm’s feed contains 6000 kg dry biomass and its livestock gain 480 kg dry biomass. A proposed system reduces animal movement and controls temperature. The farm also considers replacing part of its output with fungal mycoprotein.<\/p>", "topic": "Biomass and food security", "parts": [{"q": "Calculate biomass transfer efficiency.", "m": 2, "ms": ["Efficiency = gain / input × 100.", "480/6000 × 100 = 8%."], "answer": 8, "unit": "%"}, {"q": "Explain two reasons the remaining input biomass does not become new livestock biomass.", "m": 2, "ms": ["Some food is not digested and is egested.", "Some absorbed material is lost through respiration / excretion, such as carbon dioxide, water or urea."]}, {"q": "Explain how the proposed livestock system could increase yield and give one drawback.", "m": 3, "ms": ["Less movement reduces energy transferred in muscle activity.", "Controlled temperature reduces energy demand for keeping warm.", "A valid drawback concerns welfare, disease, cost or resource use."]}, {"q": "Explain one requirement for producing fungal mycoprotein and evaluate a potential benefit and limitation.", "m": 3, "ms": ["A suitable carbohydrate supply, oxygen for aerobic growth or controlled temperature supports fungal growth in fermenters.", "A valid benefit includes protein production with potentially less livestock demand.", "A limitation such as energy / input costs, environmental impacts or consumer acceptance must be considered."]}]}]}];
window.COURSE_META={"id": "gcse-biology", "title": "GCSE Biology", "sub": "AQA GCSE Biology (8461)", "intro": "Explore living systems, test your understanding and practise applying biology. Separate Biology content and Higher-tier lessons are labelled.", "colour": "#22815b"};
